Object.assign(window.TEM8_DICTIONARY, {"drops":{"lemma":"drop","media":{"uk":"media/uk/drop__gb_1.mp3","us":"media/us/drop__us_1.mp3"}},"dress":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/sleevelessdress.jpg"],"uk":"media/uk/dress__gb_1.mp3","us":"media/us/dress__us_1.mp3"},"oxford":{"phon":"dres","pos":"noun","senses":[{"en":"a piece of clothing that is made in one piece and hangs down to cover the body as far as the legs, sometimes reaching to below the knees, or to the ankles","cn":"连衣裙","g":"[countable]","sc":"clothes","ex":{"en":"a long white dress","cn":"白色的长连衣裙"}},{"en":"clothes of a particular type","cn":"（尤指适用于某种场合的）服装","g":"[uncountable]","sc":"clothes","ex":{"en":"to wear casual/formal dress","cn":"穿便服／正装"}},{"en":"to put clothes on yourself/somebody","cn":"穿衣服；给（某人）穿衣服","g":"[intransitive, transitive]","lab":"North American English also","sc":"clothes","ex":{"en":"I dressed quickly.","cn":"我很快穿好了衣服。"},"pos":"verb"},{"en":"to wear a particular type or style of clothes","cn":"穿…的服装","g":"[intransitive]","lab":"North American English also","sc":"clothes","ex":{"en":"to dress smartly/casually","cn":"衣着光鲜／随意"},"pos":"verb"},{"en":"to put on formal clothes","cn":"穿正式服装","g":"[intransitive]","sc":"clothes","ex":{"en":"Do they expect us to dress for dinner?","cn":"他们要求我们穿正式服装赴宴吗？"},"pos":"verb"},{"en":"to provide clothes for somebody famous","cn":"为（名人）提供服装","g":"[transitive]","sc":"clothes","ex":{"en":"He dresses many of Hollywood's most famous young stars.","cn":"他为好莱坞许多最著名的年轻明星提供服装。"},"pos":"verb"},{"en":"to clean, treat and cover a wound","cn":"清洗包扎，敷裹（伤口）","g":"[transitive]","sc":"wound","ex":{"en":"The nurse will dress that cut for you.","cn":"护士将为你包扎那个伤口。"},"pos":"verb"},{"en":"to prepare food for cooking or eating","cn":"（烹调前）准备，处理；（食用前）给…加调味酱","g":"[transitive]","sc":"food","ex":{"en":"to dress a salad (= put oil or vinegar, etc. on it)","cn":"给色拉加调味酱（放油、醋等）"},"pos":"verb"},{"en":"to decorate or arrange something","cn":"装饰；布置","g":"[transitive]","lab":"formal","sc":"decorate/arrange","ex":{"en":"to dress a shop window (= arrange a display of clothes or goods in it)","cn":"布置橱窗"},"pos":"verb"},{"en":"to prepare a material such as stone, wood, leather, etc. for use","cn":"加工；处理；修整","g":"[transitive]","sc":"stone/wood/leather","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"连衣裙","en":"A dress is a piece of clothing worn by a woman or girl. It covers her body and part of her legs.","ex":{"en":"She was wearing a black dress.","cn":"她穿一条黑色连衣裙。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"衣服","en":"You can refer to clothes worn by men or women as dress .","ex":{"en":"He's usually smart in his dress.","cn":"他通常穿得很精神。"}},{"pos":"VERB 动词","cn":"穿衣","en":"When you dress or dress yourself, you put on clothes.","ex":{"en":"He told Sarah to wait while he dressed","cn":"他让萨拉等他穿好衣服。"}},{"pos":"VERB 动词","cn":"给…穿衣服","en":"If you dress someone, for example a child, you put clothes on them. →see usage note at:","ex":{"en":"She bathed her and dressed her in clean clothes.","cn":"她给她洗澡并穿上干净的衣服。"}},{"pos":"VERB 动词","cn":"穿着;打扮","en":"If someone dresses in a particular way, they wear clothes of a particular style or colour.","ex":{"en":"He dresses in a way that lets everyone know he's got authority","cn":"他的穿着打扮让大家都知道他已经掌权了。"}},{"pos":"VERB 动词","cn":"穿礼服","en":"If you dress for something, you put on special clothes for it.","ex":{"en":"We don't dress for dinner here.","cn":"我们这儿赴宴不穿礼服。"}},{"pos":"VERB 动词","cn":"清洗,包扎,敷裹(伤口)","en":"When someone dresses a wound, they clean it and cover it.","ex":{"en":"The poor child never cried or protested when I was dressing her wounds.","cn":"我给这个可怜的孩子包扎伤口时,她不哭也不闹。"}},{"pos":"VERB 动词","cn":"调制,加作料于(色拉)","en":"If you dress a salad, you cover it with a mixture of oil, vinegar, and herbs or flavourings.","ex":{"en":"Scatter the tomato over, then dress the salad.","cn":"把西红柿散放在上面,然后给色拉加调味汁。"}},{"pos":"VERB 动词","cn":"(在烹饪前)清洗,加工处理(鸡、鱼或肉类)","en":"To dress meat, chicken, or fish means to prepare it for cooking by cleaning it and removing the parts that you cannot eat.","ex":{"en":"Her mother dressed the meat.","cn":"她母亲把肉洗好了。"}},{"pos":"","cn":"","en":"相关词组：dress down dress up"}]},"examples":[{"en":"He dresses many of Hollywood's most famous young stars.","cn":"他为好莱坞许多最著名的年轻明星提供服装。"},{"en":"However much you try to dress it up, office work is not glamorous.","cn":"无论你怎样夸饰，办公室工作都不令人向往。"}]},"dread":{"oxford":{"phon":"dred","pos":"verb","senses":[{"en":"to be very afraid of something; to fear that something bad is going to happen","cn":"非常害怕；极为担心","ex":{"en":"This was the moment he had been dreading.","cn":"这是他一直最担心的时刻。"}},{"en":"a feeling of great fear about something that might or will happen in the future; a thing that causes this feeling","cn":"恐惧；令人惧怕的事物","g":"[uncountable, countable, usually singular]","ex":{"en":"The prospect of growing old fills me with dread.","cn":"想到人会一天天老下去便使我充满恐惧。"},"pos":"noun"},{"en":"dreadlocks (= hair that is twisted into long thick pieces that hang down from the head, worn especially by Rastafarians)","cn":"（尤指拉斯塔法里教派成员蓄的）长发绺，脏辫","g":"[plural]","lab":"informal","pos":"noun"},{"en":"dreaded (= causing fear)","cn":"恐惧；令人惧怕的事物","pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"非常担心;极为害怕","en":"If you dread something which may happen, you feel very anxious and unhappy about it because you think it will be unpleasant or upsetting.","ex":{"en":"I'm dreading Christmas this year","cn":"今年我非常害怕过圣诞节。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"忧虑;恐惧","en":"Dread is a feeling of great anxiety and fear about something that may happen.","ex":{"en":"She thought with dread of the cold winters to come.","cn":"她害怕即将来临的寒冷冬季。"}},{"pos":"ADJ 形容词","cn":"可怕的;令人畏惧的","en":"Dread means terrible and greatly feared.","ex":{"en":"...a more effective national policy to combat this dread disease.","cn":"对抗这可怕疾病的更有效的国家政策"}},{"pos":"ADJ 形容词","cn":"恼火的;生气的;不想要的","en":"You can use dread to describe something that you, or a particular group of people, find annoying or undesirable.","ex":{"en":"...the dread phrase 'politically correct'.","cn":"令人不快的短语“政治上正确”"}},{"pos":"PHRASE 短语","cn":"不敢想","en":"If you say that you dread to think what might happen, you mean that you are anxious about it because it is likely to be very unpleasant.","ex":{"en":"I dread to think what will happen in the case of a major emergency","cn":"我不敢想在重大紧急情况下会发生什么。"}}]},"media":{"uk":"media/uk/dread__gb_1.mp3","us":"media/us/dread__us_1.mp3"},"examples":[{"en":"The committee members live in dread of (= are always worried about) anything that may cause a scandal.","cn":"委员会成员整天提心吊胆，生怕有什么事会引起流言蜚语。"},{"en":"I dread to think what would happen if there really was a fire here.","cn":"我不敢想像假如这儿真的发生火灾会是什么情景。"}]},"dried":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(食物或牛奶)干的,脱水的","en":"Dried food or milk has had all the water removed from it so that it will last for a long time.","ex":{"en":"...an infusion which may be prepared from the fresh plant or the dried herb","cn":"可以用新鲜植物或干药草泡制的浸剂"}}]},"media":{"uk":"media/uk/dried__gb_1.mp3","us":"media/us/dried__us_1.mp3"},"examples":[{"en":"dried herbs","cn":"干药草"}],"oxford":{"phon":"draɪd","pos":"adjective","senses":[{"en":"with all the liquid removed in order to preserve something","cn":"干的；脱水的","ex":{"en":"dried flowers/apricots","cn":"干花；杏干"}}]},"base":"dry"},"drove":{"media":{"uk":"media/uk/drove__gb_2.mp3","us":"media/us/drove__us_2.mp3"},"oxford":{"phon":"drəʊv","pos":"noun","senses":[{"en":"a large number of people or animals, often moving or doing something as a group","cn":"（移动的）人群，畜群","ex":{"en":"droves of tourists","cn":"成群的游客"}}]},"examples":[{"en":"People were leaving the countryside in droves to look for work in the cities.","cn":"一批一批的人离开农村到城里找工作。"},{"en":"droves of tourists","cn":"成群的游客"}],"collins":{"senses":[{"pos":"","cn":"","en":"Drove is the past tense of drive."}]},"base":"drive"},"driveway":{"media":{"uk":"media/uk/driveway__gb_1.mp3","us":"media/us/driveway__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"私家车道","en":"A driveway is a piece of hard ground that leads from the road to the front of a house or other building."}]},"examples":[{"en":"There was a car parked in/on the driveway.","cn":"有一辆汽车停在车道上。"}],"oxford":{"phon":"ˈdraɪvweɪ","pos":"noun","senses":[{"en":"a wide hard path or a private road that leads from the street to a house","cn":"（从街道通向住宅的宽阔或私人的）车道","ex":{"en":"There was a car parked on/on the driveway.","cn":"车道上停着一辆车。"}}]}},"dressed":{"media":{"uk":"media/uk/dressed__gb_1.mp3","us":"media/us/dressed__us_1.mp3"},"oxford":{"phon":"drest","pos":"adjective","senses":[{"en":"wearing clothes and not naked or wearing clothes for sleeping","cn":"穿着衣服","ex":{"en":"Hurry up and get dressed.","cn":"快点穿上衣服。"}},{"en":"wearing clothes of a particular type","cn":"穿着…服装","ex":{"en":"She is always so smartly dressed.","cn":"她总是穿得那么讲究。"}},{"en":"cleaned and prepared for cooking or eating","cn":"（为烹调或食用）加工好的","ex":{"en":"Place a spoonful of the dressed crab on each plate.","cn":"在每个盘子上放一勺处理好的螃蟹。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"穿着衣服的;穿着整齐的","en":"If you are dressed, you are wearing clothes rather than being naked or wearing your night clothes. If you get dressed, you put on your clothes. →see usage note at:","ex":{"en":"He was fully dressed, including shoes","cn":"他穿戴整齐,鞋都穿好了。"}},{"pos":"ADJ 形容词","cn":"穿着…衣服的;作…打扮的","en":"If you are dressed in a particular way, you are wearing clothes of a particular colour or kind.","ex":{"en":"...a tall thin woman dressed in black.","cn":"一个穿着黑衣服的瘦高女子"}},{"pos":"PHRASE 短语","cn":"打扮得引人注目;打扮得花枝招展;衣着光鲜","en":"If someone is dressed to kill, they are wearing very smart or fashionable clothes because they want people to notice them and think they are attractive.","ex":{"en":"...a solitary blonde, beautiful, haughty and dressed to kill.","cn":"一位漂亮孤傲、打扮时髦的金发女郎"}}]},"examples":[{"en":"He was casually dressed in jeans and a T-shirt.","cn":"他穿着很随便的牛仔裤和 T 恤衫。"},{"en":"I can't go to the door — I'm not dressed yet.","cn":"我没法去开门，我还没穿好衣服呢。"}],"base":"dress"},"dry":{"media":{"uk":"media/uk/dry__gb_1.mp3","us":"media/us/dry__us_1.mp3"},"oxford":{"phon":"draɪ","pos":"adjective","senses":[{"en":"not wet or sticky; without water or moisture","cn":"干的；干燥的","sc":"not wet","ex":{"en":"Is my shirt dry yet?","cn":"我的衬衣干了吗？"}},{"en":"with very little rain","cn":"雨少的；干旱的；干燥的","sc":"little rain","ex":{"en":"weeks of hot, dry weather","cn":"连续几周炎热干燥的天气"}},{"en":"without the natural oils that makes it soft and healthy","cn":"干性的；无水分的","sc":"skin/hair","ex":{"en":"a shampoo for dry hair","cn":"适合干性发质的洗发水"}},{"en":"that does not produce any phlegm (= the thick liquid that forms in the nose and throat)","cn":"干咳的","sc":"cough","ex":{"en":"a dry hacking cough","cn":"猛烈的干咳"}},{"en":"eaten on its own without any butter, jam, etc.","cn":"无黄油（或果酱等）的","sc":"bread","ex":{"en":"Breakfast consisted of dry bread and a cup of tea.","cn":"早餐有不涂黄油的面包和一杯茶。"}},{"en":"not sweet","cn":"无甜味的；干的","sc":"wine","ex":{"en":"a crisp dry white wine","cn":"爽口的干白葡萄酒"}},{"en":"very clever and expressed in a quiet way that is not obvious; often using irony","cn":"机敏的；不形于色的；不露声色的","lab":"approving","sc":"humour","ex":{"en":"He was a man of few words with a delightful dry sense of humour.","cn":"他话不多，却富有不形于色的幽默感，让人很愉快。"}},{"en":"not showing emotion","cn":"不动感情的；冷冰冰的","sc":"without emotion","ex":{"en":"a dry voice","cn":"冷冰冰的声音"}},{"en":"not interesting","cn":"干巴巴的；枯燥乏味的","sc":"boring","ex":{"en":"Government reports tend to make dry reading.","cn":"政府报告读起来往往枯燥无味。"}},{"en":"without alcohol; where it is illegal to buy, sell or drink alcohol","cn":"无酒的；禁酒的；戒酒的","sc":"without alcohol","ex":{"en":"We had a dry wedding (= no alcoholic drinks were served).","cn":"我们举行了一个无酒的婚礼。"}},{"en":"thirsty; that makes you thirsty","cn":"口渴的；令人口渴的","lab":"informal, especially British English，，","sc":"thirsty","ex":{"en":"I'm a bit dry.","cn":"我有点渴。"}},{"en":"a dry place","cn":"干的地方；干燥处","ex":{"en":"You must be so wet! Come into the dry.","cn":"你一定湿透了！快到干的地方来。"},"pos":"noun"},{"en":"the dry season","cn":"旱季","lab":"especially Australian English","ex":{"en":"The dry had started and the grass was turning yellow.","cn":"旱季已来临，草开始枯黄。"},"pos":"noun"},{"en":"to become dry; to make something dry","cn":"（使）变干；（把…）弄干","ex":{"en":"He did the laundry and hung it out to dry.","cn":"他洗完衣服并把它挂起来晾干。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"干的;干燥的","en":"If something is dry, there is no water or moisture on it or in it.","ex":{"en":"Clean the metal with a soft dry cloth","cn":"用柔软的干布擦拭金属。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变干;弄干;擦干","en":"When something dries or when you dry it, it becomes dry.","ex":{"en":"The washing might dry outside today, the sun's shining","cn":"洗过的衣物可能今天晾在外面就能干,阳光正足。"}},{"pos":"VERB 动词","cn":"(洗后）擦干(盘、杯、刀、锅等)","en":"When you dry the dishes after a meal, you wipe the water off the plates, cups, knives, pans, and other things when they have been washed, using a cloth.","ex":{"en":"Mrs. Madrigal began drying dishes.","cn":"马德里加尔夫人开始擦干碟子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(皮肤或头发)发干的,无水分的","en":"If you say that your skin or hair is dry, you mean that it is less oily than, or not as soft as, normal.","ex":{"en":"Nothing looks worse than dry, cracked lips","cn":"没有什么比干燥开裂的嘴唇更难看的了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"干旱的;雨量少的;无雨的","en":"If the weather or a period of time is dry, there is no rain or there is much less rain than average.","ex":{"en":"Exceptionally dry weather over the past year had cut agricultural production","cn":"去年罕见的干旱天气已导致农业减产。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方或气候)少雨的,干燥的","en":"A dry place or climate is one that gets very little rainfall.","ex":{"en":"It was one of the driest and dustiest places in Africa.","cn":"那是非洲最干旱、尘土最多的地方之一。"}},{"pos":"N-SING 单数名词","cn":"干燥;少雨","en":"In the dry means in a place or at a time that is not damp, wet, or rainy.","ex":{"en":"Such cars, however, do grip the road well, even in the dry.","cn":"不过，这种车即使在干燥路面上也表现出了良好的抓地性能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(通常指河流、湖泊或水井由于天热少雨而)干涸的","en":"If a river, lake, or well is dry, it is empty of water, usually because of hot weather and lack of rain.","ex":{"en":"The aquifer which had once fed the wells was pronounced dry","cn":"曾为水井供水的蓄水层正式宣告干涸了。"}},{"pos":"ADJ 形容词","cn":"(油井)枯竭的,不再产油的","en":"If an oil well is dry, it is no longer producing any oil.","ex":{"en":"To harvest oil and gas profitably from the North Sea, it must focus on the exploitation of small reserves as the big wells run dry.","cn":"随着大型油井的枯竭，要想从北海的石油和天然气开采中盈利,必须着力于开采小储量的油井。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"口渴的;干渴的","en":"If you are dry, you need to drink something.","ex":{"en":"She was suddenly thirsty and dry.","cn":"她突然口渴了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因紧张、生病等)口干的,喉咙干的","en":"If your mouth or throat is dry, it has little or no saliva in it, and so feels very unpleasant, perhaps because you are tense or ill.","ex":{"en":"His mouth was dry, he needed a drink","cn":"他口很干,需要喝上一杯。"}},{"pos":"ADJ 形容词","cn":"(咳嗽)无痰的,干咳的","en":"A dry cough is one that does not produce any mucus."},{"pos":"ADJ 形容词","cn":"(眼睛)无泪的","en":"If someone has dry eyes, there are no tears in their eyes; often used with negatives or in contexts where you are expressing surprise that they are not crying.","ex":{"en":"There were few dry eyes in the house when I finished","cn":"我说完后房间里没几个人不掉泪的。"}},{"pos":"ADJ 形容词","cn":"禁酒的","en":"If a country, state, or city is dry, it has laws or rules which forbid anyone to drink, sell, or buy alcoholic drink.","ex":{"en":"Gujurat has been a totally dry state for the past thirty years.","cn":"在过去的 30 年里古吉拉特一直是完全禁酒的一个州。"}},{"pos":"ADJ 形容词","cn":"（被）吸干的;（被）榨干的","en":"If you say that someone is sucking something dry or milking it dry, you are criticizing them for taking all the good things from it until there is nothing left.","ex":{"en":"...a shady rip-off industry that sucks its talent dry then discards it","cn":"见不得人的山寨行业吸干了它的才华后又将它抛弃"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(幽默)不露声色的,含蓄不露的,机敏的","en":"Dry humour is very amusing, but in a subtle and clever way.","ex":{"en":"Fulton has retained his dry humour","cn":"富尔顿保持着他含而不露的幽默。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷淡的;淡然的;不动感情的;冷冰冰的","en":"If you describe a voice as dry, you mean that it is cold or dull, and does not express any emotions.","ex":{"en":"When he crept back to his desk, he heard the dry voice of Father Laurence.","cn":"当他轻手轻脚地回到读经台时,他听到了劳伦斯神父冷冰冰的声音。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"枯燥乏味的;干巴巴的;无趣的","en":"If you describe something such as a book, play, or activity as dry, you mean that it is dull and uninteresting.","ex":{"en":"...dry, academic phrases.","cn":"枯燥无味的学术词汇"}},{"pos":"ADJ 形容词","cn":"(面包或吐司)不涂黄油和果酱的","en":"Dry bread or toast is plain and not covered with butter or jam.","ex":{"en":"For breakfast, they had dry bread and tea.","cn":"他们早餐吃了无黄油的面包，还喝了茶。"}},{"pos":"ADJ 形容词","cn":"(酒)无甜味的,干的","en":"Dry sherry or wine does not have a sweet taste.","ex":{"en":"...a glass of chilled, dry white wine.","cn":"一杯冰镇干白葡萄酒"}},{"pos":"","cn":"","en":"high and dry→see: ; home and dry→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"(河流、湖泊或水井)干涸","en":"If a river, lake, or well dries up, it becomes empty of water, usually because of hot weather and a lack of rain.","ex":{"en":"Reservoirs are drying up and farmers have begun to leave their land","cn":"水库逐渐干涸,农民开始背井离乡。"}},{"pos":"PHRASAL VERB 短语动词","cn":"（供应）枯竭，停止，中断","en":"If a supply of something dries up, it stops.","ex":{"en":"Investment could dry up and that could cause the economy to falter","cn":"投资可能会中断,而这会引起经济衰退。"}},{"pos":"PHRASAL VERB 短语动词","cn":"无话可说;突然住口","en":"If you dry up when you are speaking, you stop in the middle of what you were saying, because you cannot think what to say next.","ex":{"en":"If you ask her what she's good at she will dry up after two minutes.","cn":"如果你问她擅长什么，两分钟后她就没话说了。"}},{"pos":"","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：dry off dry out dry up"}]},"examples":[{"en":"As she got older, offers of modelling work began to dry up.","cn":"随着她年龄渐长，邀请她做模特儿的工作已越来越少。"},{"en":"He was a man of few words with a delightful dry sense of humour.","cn":"他话不多，却富有不形于色的幽默感，让人很欣赏。"}]},"dreamily":{"media":{"uk":"media/uk/dreamily__gb_1.mp3","us":"media/us/dreamily__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"出神地;想入非非地;心不在焉地","en":"If you say or do something dreamily, you say or do it in a way that shows your mind is occupied with pleasant, relaxing thoughts.","ex":{"en":"'They were divine,' she sighs, dreamily","cn":"“他们是神圣的,”她神情恍惚地叹了口气。"}}]},"examples":[{"en":"‘I’m coming,’ he replied dreamily, without moving. “","cn":"我就来。”他心不在焉地回答着﹐动都没有动一下。"}],"oxford":{"phon":"ˈdriːmɪli","pos":"adverb","senses":[{"en":"as though you are thinking about other things and not paying attention to what is happening around you","cn":"做白日梦的；心不在焉的","ex":{"en":"‘I have lots of happy memories,’ she said dreamily.","cn":"“我有很多快乐的回忆，”她梦幻般地说。"}},{"en":"in a pleasant and gentle way, as if in a dream","cn":"梦：以求的：以一种愉快而温柔的方式，就像在梦中一样","ex":{"en":"It was only in the dreamily evocative last movement that the orchestra really came together.","cn":"直到最后乐章如梦似幻，乐团才真正团结起来。"}}]}},"drew":{"lemma":"draw","media":{"uk":"media/uk/drew__gb_1.mp3","us":"media/us/drew__us_1.mp3"}},"driven":{"media":{"uk":"media/uk/driven__gb_2.mp3","us":"media/us/driven__us_2.mp3"},"oxford":{"phon":"ˈdrɪvn","pos":"adjective","senses":[{"en":"determined to succeed, and working very hard to do so","cn":"奋发努力的；发愤图强的"},{"en":"influenced or caused by a particular thing","cn":"受…影响的；由…造成的","ex":{"en":"a market-driven economy","cn":"市场导向的经济"}}]},"examples":[{"en":"a character-driven movie","cn":"以人物为主的电影"},{"en":"a market-driven economy","cn":"市场导向的经济"}],"collins":{"senses":[{"pos":"","cn":"","en":"Driven is the past participle of drive."}]},"base":"drive"},"drawback":{"media":{"uk":"media/uk/drawback__gb_1.mp3","us":"media/us/drawback__us_1.mp3"},"oxford":{"phon":"ˈdrɔːbæk","pos":"noun","senses":[{"en":"a disadvantage or problem that makes something a less attractive idea","cn":"缺点；不利条件","ex":{"en":"The main drawback to it is the cost.","cn":"它的主要缺点是成本高。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缺点;缺陷;不利条件","en":"A drawback is an aspect of something or someone that makes them less acceptable than they would otherwise be.","ex":{"en":"He felt the apartment's only drawback was that it was too small.","cn":"他觉得这个公寓唯一的缺点就是太小了。"}}]},"examples":[{"en":"The main drawback to it is the cost.","cn":"它的主要缺点是成本高。"},{"en":"This is the one major drawback of the new system.","cn":"这是新系统的一大弊端。"}]},"dreadful":{"media":{"uk":"media/uk/dreadful__gb_1.mp3","us":"media/us/dreadful__us_1.mp3"},"oxford":{"phon":"ˈdredfl","pos":"adjective","senses":[{"en":"very bad or unpleasant","cn":"糟糕透顶的；讨厌的；令人不快的","lab":"especially British English","ex":{"en":"What dreadful weather!","cn":"多么讨厌的天气！"}},{"en":"used to emphasize how bad something is","cn":"（强调糟糕的程度）极其的，极坏的","g":"[only before noun]","ex":{"en":"He’s a dreadful snob.","cn":"他是个可怕的势利小人。"}},{"en":"causing fear, pain or difficulty","cn":"可怕的；使人痛苦的；艰难的","g":"[usually before noun]","ex":{"en":"a dreadful accident","cn":"可怕的事故"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糟糕透顶的;令人不快的;劣质的","en":"If you say that something is dreadful, you mean that it is very bad or unpleasant, or very poor in quality.","ex":{"en":"They told us the dreadful news","cn":"他们告诉了我们那糟糕透顶的消息。"}},{"pos":"ADJ 形容词","cn":"极严重的","en":"Dreadful is used to emphasize the degree or extent of something bad.","ex":{"en":"We've made a dreadful mistake","cn":"我们犯了个极大的错误。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(看上去或感觉到)病得不轻的,极度疲惫的,非常沮丧的","en":"If someone looks or feels dreadful, they look or feel very ill, tired, or upset.","ex":{"en":"Are you all right? You look dreadful","cn":"你还好吧？你看上去十分疲惫。"}}]},"examples":[{"en":"It's dreadful the way they treat their staff.","cn":"他们对待雇员的方式糟糕透了。"},{"en":"She's making a dreadful mess of things.","cn":"她把事情搞得一塌糊涂。"}]},"drying":{"lemma":"dry","media":{"uk":"media/uk/dry__gb_1.mp3","us":"media/us/dry__us_1.mp3"}},"driver":{"media":{"uk":"media/uk/driver__gb_1.mp3","us":"media/us/driver__us_1.mp3"},"oxford":{"phon":"ˈdraɪvə(r)","pos":"noun","senses":[{"en":"a person who drives a vehicle","cn":"驾驶员；司机；驾车者","lab":"British English","ex":{"en":"a bus/train/taxi driver","cn":"公共汽车／火车／出租车司机"}},{"en":"a club with a large head, used for hitting the ball long distances from the tee","cn":"开球杆；一号木"},{"en":"software that controls the sending of data between a computer and a piece of equipment that is attached to it, such as a printer","cn":"驱动程序","lab":"computing","ex":{"en":"I downloaded and installed the drivers.","cn":"我下载并安装了驱动程序。"}},{"en":"one of the main things that influence something or cause it to make progress","cn":"驱动因素","ex":{"en":"Housing is a key driver of the economy.","cn":"住房是个促使经济增长的主要因素。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"驾驶员;司机;驾车者","en":"The driver of a vehicle is the person who is driving it.","ex":{"en":"The driver got out of his van.","cn":"司机从货车上下来。"}},{"pos":"N-COUNT 可数名词","cn":"驱动程序","en":"A driver is a computer program that controls a device such as a printer.","ex":{"en":"...printer driver software.","cn":"打印机驱动软件"}}]},"examples":[{"en":"Housing is a key driver of the economy.","cn":"住房是个促使经济增长的主要因素。"},{"en":"The car comes equipped with a driver's airbag.","cn":"这辆汽车装有驾驶员安全气囊。"}]},"dream":{"media":{"uk":"media/uk/dream__gb_1.mp3","us":"media/us/dream__us_1.mp3"},"oxford":{"phon":"driːm","pos":"noun","senses":[{"en":"a series of images, events and feelings that happen in your mind while you are asleep","cn":"梦；睡梦","g":"[countable]","ex":{"en":"I had a really weird dream last night.","cn":"我昨晚做了个很离奇的梦。"}},{"en":"a wish to have or be something, especially one that seems difficult to achieve","cn":"梦想；理想；愿望","g":"[countable]","ex":{"en":"Her lifelong dream was to be a famous writer.","cn":"她的毕生愿望就是成为名作家。"}},{"en":"a state of mind or a situation in which things do not seem real or part of normal life","cn":"梦幻状态；恍惚；出神","g":"[singular]","ex":{"en":"She walked around in a dream all day.","cn":"她整天都在梦游似的到处转悠。"}},{"en":"a beautiful or wonderful person or thing","cn":"梦一般美妙的人（或事物）；极美好的人（或事物）","g":"[singular]","lab":"informal","ex":{"en":"That meal was an absolute dream.","cn":"那顿饭真是太棒了。"}},{"en":"to experience a series of images, events and feelings in your mind while you are asleep","cn":"做梦；梦见","g":"[intransitive, transitive]","ex":{"en":"Did I talk in my sleep? I must have been dreaming.","cn":"我说梦话了吗？我肯定是在做梦。"},"pos":"verb"},{"en":"to imagine and think about something that you would like to happen","cn":"想象；梦想","g":"[intransitive, transitive]","ex":{"en":"It might never happen, but I can dream can't I?","cn":"也许永远不会成真，但我可以有梦想，不是吗？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"梦","en":"A dream is an imaginary series of events that you experience in your mind while you are asleep.","ex":{"en":"He had a dream about Claire","cn":"他梦见了克莱尔。"}},{"pos":"VERB 动词","cn":"做梦;梦见;梦到","en":"When you dream, you experience imaginary events in your mind while you are asleep.","ex":{"en":"Ivor dreamed that he was on a bus","cn":"艾弗梦见他在一辆公共汽车上。"}},{"pos":"N-COUNT 可数名词","cn":"梦想;幻想;愿望","en":"You can refer to a situation or event as a dream if you often think about it because you would like it to happen.","ex":{"en":"He had finally accomplished his dream of becoming a pilot","cn":"他最终实现了成为一名飞行员的梦想。"}},{"pos":"VERB 动词","cn":"梦想;渴望","en":"If you often think about something that you would very much like to happen or have, you can say that you dream of it.","ex":{"en":"As a schoolgirl, she had dreamed of becoming an actress","cn":"她上学时曾梦想成为一名女演员。"}},{"pos":"ADJ 形容词","cn":"理想的;梦幻般的;完美的","en":"You can use dream to describe something that you think is ideal or perfect, especially if it is something that you thought you would never be able to have or experience.","ex":{"en":"He had his dream house built on the banks of the river Bure.","cn":"他在布尔河畔建造了他的梦幻屋。"}},{"pos":"N-SING 单数名词","cn":"理想;夙愿;梦寐以求的事物","en":"If you describe something as a particular person's dream, you think that it would be ideal for that person and that he or she would like it very much.","ex":{"en":"Greece is said to be a botanist's dream","cn":"据说希腊是植物学家梦寐以求的地方。"}},{"pos":"N-SING 单数名词","cn":"美妙的事;美好的事","en":"If you say that something is a dream, you mean that it is wonderful."},{"pos":"N-COUNT 可数名词","cn":"空想;胡思乱想","en":"You can refer to a situation or event that does not seem real as a dream, especially if it is very strange or unpleasant.","ex":{"en":"When the right woman comes along, this bad dream will be over.","cn":"当有合适的女人出现时,这种胡思乱想就会停止了。"}},{"pos":"VERB 动词","cn":"绝不;无论如何也不","en":"If you say that you would not dream of doing something, you are emphasizing that you would never do it because you think it is wrong or is not possible or suitable for you.","ex":{"en":"I wouldn't dream of making fun of you","cn":"我绝不会取笑你。"}},{"pos":"VERB 动词","cn":"想到;料到","en":"If you say that you never dreamed that something would happen, you are emphasizing that you did not think that it would happen because it seemed very unlikely.","ex":{"en":"I never dreamed that I would be able to afford a home here","cn":"我从没想到我在这儿能买得起房子。"}},{"pos":"PHRASE 短语","cn":"痴心妄想","en":"If you tell someone to dream on, you mean that something they are hoping for is unlikely to happen.","ex":{"en":"'Perhaps one day I may go on a relaxing holiday.' — 'Yeah, dream on.'","cn":"“也许有一天我可以享受一个放松身心的假期。”——“是啊,你就做梦吧。”"}},{"pos":"PHRASE 短语","cn":"心不在焉;梦游般地","en":"If you say that you are in a dream, you mean that you do not concentrate properly on what you are doing because you are thinking about other things.","ex":{"en":"All day long I moved in a dream.","cn":"整整一天我都心不在焉。"}},{"pos":"PHRASE 短语","cn":"梦幻般地;美妙地;完美地","en":"If you say that someone does something like a dream, you think that they do it very well. If you say that something happens like a dream, you mean that it happens successfully without any problems.","ex":{"en":"She cooked like a dream","cn":"她烹饪技艺精湛。"}},{"pos":"PHRASE 短语","cn":"理想中的;完美的","en":"If you describe someone or something as the person or thing of your dreams, you mean that you consider them to be ideal or perfect.","ex":{"en":"This could be the man of my dreams.","cn":"这就是我理想中的男子。"}},{"pos":"PHRASE 短语","cn":"（强调极为奇怪或完全不可能）再怎么想也","en":"If you say that you could not imagine a particular thing in your wildest dreams, you are emphasizing that you think it is extremely strange or unlikely.","ex":{"en":"Never in my wildest dreams did I think we could win.","cn":"我做梦也没想到我们会赢。"}},{"pos":"PHRASE 短语","cn":"超出想象的;比希望中要好的","en":"If you describe something as being beyond your wildest dreams, you are emphasizing that it is better than you could have imagined or hoped for.","ex":{"en":"She had already achieved success beyond her wildest dreams.","cn":"她已经取得超乎想象的成功。"}},{"pos":"","cn":"","en":"相关词组：dream up"}]},"examples":[{"en":"In broad daylight the events of the night before seemed like a bad dream.","cn":"在大白天里，前一天夜里发生的事情就像噩梦般令人难以置信。"},{"en":"‘I'll be a manager before I'm 30.’ ‘In your dreams.’ “","cn":"我要在 30 岁前当经理。” “你做梦。”"}]},"draw":{"media":{"uk":"media/uk/draw__gb_1.mp3","us":"media/us/draw__us_1.mp3"},"oxford":{"phon":"drɔː","pos":"verb","senses":[{"en":"to make pictures, or a picture of something, with a pencil, pen or chalk (but not paint)","cn":"（用铅笔、钢笔或粉笔）画，描绘，描画","g":"[intransitive, transitive]","lab":"US English","sc":"make pictures","ex":{"en":"You draw beautifully.","cn":"你的画画得真好。"}},{"en":"to describe something in words in a way that produces an image in somebody's mind","cn":"（用语言）描绘，描述","g":"[transitive]","sc":"describe in words","ex":{"en":"The report drew a grim picture of inefficiency and corruption.","cn":"这份报告描绘了一幅办事效率低下和贪污腐化的可怕景象。"}},{"en":"to have a particular idea after you have studied something or thought about it","cn":"获取；得出；推断出","g":"[transitive]","sc":"conclusion","ex":{"en":"Is it possible to draw inferences about the environment during the Bronze Age?","cn":"是否可以推断青铜时代的环境？"}},{"en":"to express a comparison or a contrast; to define the limits of something","cn":"作（比较或对比）；界定（范围）","g":"[transitive]","sc":"comparison/limits","ex":{"en":"to draw a comparison/a parallel/an analogy/a distinction between two events","cn":"比较／对比两件事"}},{"en":"to produce a reaction or response","cn":"产生，引起，激起（反应或回应）","g":"[transitive]","sc":"get reaction","ex":{"en":"The plan has drawn a lot of criticism.","cn":"这个计划引来众多批评。"}},{"en":"to direct or attract somebody's attention to something","cn":"转移，吸引（注意力）","g":"[transitive]","sc":"get reaction","ex":{"en":"Our aim is to draw attention to the plight of these children.","cn":"我们的目的是提请人们注意这些儿童的困境。"}},{"en":"to attract or interest somebody","cn":"吸引；招引；使感兴趣","g":"[transitive]","sc":"attract","ex":{"en":"The movie is drawing large audiences.","cn":"这部影片吸引着大批观众。"}},{"en":"to move in the direction mentioned","cn":"（向某个方向）移动，行进","g":"[intransitive]","lab":"figurative","sc":"move","ex":{"en":"The train drew into the station.","cn":"火车徐徐驶入车站。"}},{"en":"to move something/somebody by pulling it or them gently","cn":"拖（动）；拉（动）；牵引","g":"[transitive]","lab":"figurative","sc":"pull","ex":{"en":"He drew the cork out of the bottle.","cn":"他把瓶塞拔了出来。"}},{"en":"to pull a vehicle such as a carriage","cn":"拉，拖（车）","g":"[transitive, often passive]","sc":"pull","ex":{"en":"The Queen's coach was drawn by six horses.","cn":"女王的御驾是由六匹马拉的。"}},{"en":"to open or close curtains, etc.","cn":"拉（窗帘等）","g":"[transitive]","sc":"curtains","ex":{"en":"The blinds were drawn.","cn":"窗帘拉上了。"}},{"en":"to take out a weapon, such as a gun or a sword, in order to attack somebody","cn":"拔出；抽出；掏出","g":"[transitive, intransitive]","sc":"weapon","ex":{"en":"She drew a revolver on me.","cn":"她拔出左轮手枪对准我。"}},{"en":"to make somebody say more about something","cn":"使说出；使吐露","g":"[transitive]","sc":"make somebody talk","ex":{"en":"Spielberg refused to be drawn on his next movie.","cn":"斯皮尔伯格拒绝透露他下一部影片的任何消息。"}},{"en":"to decide something by picking cards, tickets or numbers by chance","cn":"抽（签、牌）；抓（阄）","g":"[intransitive, transitive]","sc":"choose","ex":{"en":"We drew for partners.","cn":"我们抓阄决定搭档。"}},{"en":"to finish a game without either team winning","cn":"以平局结束；不分胜负","g":"[intransitive, transitive]","sc":"game","ex":{"en":"England and France drew.","cn":"英格兰队和法国队打平。"}},{"en":"to take money or payments from a bank account or post office","cn":"提取；领取；支取","g":"[transitive]","sc":"money","ex":{"en":"I drew out £200.","cn":"我取了 200 英镑。"}},{"en":"to take or pull liquid or gas from somewhere","cn":"抽出；吸出","g":"[transitive]","sc":"liquid/gas","ex":{"en":"to draw water from a well","cn":"从井中抽水"}},{"en":"to breathe in smoke or air","cn":"抽（烟）；吸（气）","g":"[intransitive, transitive]","sc":"smoke/air","ex":{"en":"He drew thoughtfully on his pipe.","cn":"他若有所思地抽着烟斗。"}},{"en":"the act of choosing something, for example the winner of a prize or the teams who play each other in a competition, usually by taking pieces of paper, etc. out of a container without being able to see what is written on them","cn":"抽彩；抽奖；抽签","g":"[usually singular]","lab":"US English also","sc":"choosing","ex":{"en":"the draw for the second round of the Champions League","cn":"欧洲冠军联赛第二轮抽签"},"pos":"noun"},{"en":"a competition in which the winners are chosen in a draw","cn":"抽奖","lab":"North American English usually","sc":"choosing","ex":{"en":"a prize draw","cn":"抽奖"},"pos":"noun"},{"en":"a game in which both teams or players finish with the same number of points","cn":"平局；和局；不分胜负","lab":"especially British English","sc":"sports/games","ex":{"en":"The match ended in a two-all draw.","cn":"比赛以二平结束。"},"pos":"noun"},{"en":"a sports match for which the teams or players are chosen in a draw","cn":"由抽签决定对手的比赛","lab":"British English","sc":"sports/games","ex":{"en":"Liverpool have an away draw against Manchester United.","cn":"利物浦队抽的签是在客场与曼彻斯特联队进行比赛。"},"pos":"noun"},{"en":"a set of matches for which the teams or players are chosen in a draw","cn":"由抽签决定对手的系列比赛","g":"[usually singular]","sc":"sports/games","ex":{"en":"There are only two seeded players left in the top half of the draw.","cn":"在抽签系列比赛的上半区就只剩下两名种子选手了。"},"pos":"noun"},{"en":"a person, a thing or an event that attracts a lot of people","cn":"有吸引力的人（或事物）","sc":"attraction","ex":{"en":"She is currently one of the biggest draws on the Irish music scene.","cn":"她是目前爱尔兰音乐界最受欢迎的人物之一。"},"pos":"noun"},{"en":"an act of breathing in the smoke from a cigarette","cn":"吸烟","sc":"smoke","ex":{"en":"She took one last draw from the cigarette.","cn":"她吸了最后一口烟。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"画;描绘;描画","en":"When you draw, or when you draw something, you use a pencil or pen to produce a picture, pattern, or diagram.","ex":{"en":"She would sit there drawing with the pencil stub","cn":"她会坐在那儿用铅笔头画画。"}},{"pos":"VERB 动词","cn":"(车辆平稳地)移动，行进","en":"When a vehicle draws somewhere, it moves there smoothly and steadily.","ex":{"en":"Claire had seen the taxi drawing away","cn":"克莱尔看到出租车缓缓开走了。"}},{"pos":"VERB 动词","cn":"慢慢走;溜达","en":"If you draw somewhere, you move there slowly.","ex":{"en":"She drew away and did not smile","cn":"她慢慢走开了，脸上没有笑容。"}},{"pos":"VERB 动词","cn":"拉;拖","en":"If you draw something or someone in a particular direction, you move them in that direction, usually by pulling them gently.","ex":{"en":"He drew his chair nearer the fire","cn":"他把椅子拉到离炉火更近的位置。"}},{"pos":"VERB 动词","cn":"拉(窗帘、百叶窗等)","en":"When you draw a curtain or blind, you pull it across a window, either to cover or to uncover it.","ex":{"en":"After drawing the curtains, she lit a candle","cn":"拉上窗帘后，她点燃了蜡烛。"}},{"pos":"VERB 动词","cn":"拔出，抽出，掏出(枪、刀等武器)","en":"If someone draws a gun, knife, or other weapon, they pull it out of its container and threaten you with it.","ex":{"en":"He drew his dagger and turned to face his pursuers.","cn":"他拔出匕首转身面向追他的人。"}},{"pos":"VERB 动词","cn":"(牲畜或机动车)拖，拉","en":"If an animal or vehicle draws something such as a cart, carriage, or another vehicle, it pulls it along.","ex":{"en":"...a slow-moving tractor, drawing a trailer.","cn":"拖着一辆挂车的移动缓慢的拖拉机"}},{"pos":"VERB 动词","cn":"深深吸入(空气)","en":"If you draw a deep breath, you breathe in deeply once.","ex":{"en":"He paused, drawing a deep breath.","cn":"他停了下来，深深地吸了口气。"}},{"pos":"VERB 动词","cn":"吸（烟）","en":"If you draw on a cigarette, you breathe the smoke from it into your mouth or lungs.","ex":{"en":"He drew on an American cigarette","cn":"他抽着一根美国产的香烟。"}},{"pos":"VERB 动词","cn":"汲取;提取","en":"To draw something such as water or energy from a particular source means to take it from that source.","ex":{"en":"Villagers still have to draw their water from wells.","cn":"村民们仍然要从井里打水。"}},{"pos":"VERB 动词","cn":"放(血);抽(血)","en":"If something that hits you or presses part of your body draws blood, it cuts your skin so that it bleeds.","ex":{"en":"Any practice that draws blood could increase the risk of getting the virus.","cn":"任何引起出血的做法都可能会增加感染病毒的危险。"}},{"pos":"VERB 动词","cn":"提取，支取，领取(存款)","en":"If you draw money out of a bank, building society, or savings account, you get it from the account so that you can use it.","ex":{"en":"She was drawing out cash from a cash machine","cn":"她正从自动提款机中取钱。"}},{"pos":"VERB 动词","cn":"领取(薪水等)","en":"If you draw a salary or a sum of money, you receive a sum of money regularly.","ex":{"en":"For the first few years I didn't draw any salary at all","cn":"在开始的几年里我分文未取。"}},{"pos":"VERB 动词","cn":"(在比赛等中)抽(签);(在摸彩中)抽(奖)","en":"To draw something means to choose it or to be given it, as part of a competition, game, or lottery.","ex":{"en":"We delved through a sackful of letters to draw the winning name","cn":"我们把手探进一袋信件中抽取获奖者。"}},{"pos":"N-COUNT 可数名词","cn":"抽奖","en":"A draw is a competition where people pay money for numbered or named tickets, then some of those tickets are chosen, and the owners are given prizes."},{"pos":"VERB 动词","cn":"取得;发掘","en":"To draw something from a particular thing or place means to take or get it from that thing or place.","ex":{"en":"I draw strength from the millions of women who have faced this challenge successfully","cn":"我从数百万成功面对这种挑战的女性身上汲取力量。"}},{"pos":"VERB 动词","cn":"得出;推断出","en":"If you draw a particular conclusion, you decide that that conclusion is true.","ex":{"en":"He draws two conclusions from this","cn":"他从这件事中得出两个结论。"}},{"pos":"VERB 动词","cn":"作(比较或对比)；加以(区别)","en":"If you draw a comparison, parallel, or distinction, you compare or contrast two different ideas, systems, or other things.","ex":{"en":"...literary critics drawing comparisons between George Sand and George Eliot","cn":"将乔治·桑德和乔治·艾略特进行比较的文学评论家"}},{"pos":"VERB 动词","cn":"使注意;引起…注意","en":"If you draw someone's attention to something, you make them aware of it or make them think about it.","ex":{"en":"He was waving his arms to draw their attention","cn":"他正挥手以引起他们的注意。"}},{"pos":"VERB 动词","cn":"引起(某种反应)","en":"If someone or something draws a particular reaction, people react to it in that way.","ex":{"en":"Such a policy would inevitably draw fierce resistance from farmers.","cn":"这种政策必然会招致农场主的强烈抵制。"}},{"pos":"VERB 动词","cn":"吸引","en":"If something such as a film or an event draws a lot of people, it is so interesting or entertaining that a lot of people go to it.","ex":{"en":"The game is currently drawing huge crowds.","cn":"这个游戏现在吸引了很多人。"}},{"pos":"VERB 动词","cn":"使倾心;使动心;强烈吸引","en":"If someone or something draws you, it attracts you very strongly.","ex":{"en":"He drew and enthralled her","cn":"他令她动心，让她着迷。"}},{"pos":"VERB 动词","cn":"使回答;使透露消息;使说出意见","en":"If someone will not be drawn or refuses to be drawn, they will not reply to questions in the way that you want them to, or will not reveal information or their opinion.","ex":{"en":"The ambassador would not be drawn on questions of a political nature","cn":"大使不会对政治问题发表意见。"}},{"pos":"V-RECIP 相互动词","cn":"打成平手;不分胜负","en":"In a game or competition, if one person or team draws with another one, or if two people or teams draw, they have the same number of points or goals at the end of the game.","ex":{"en":"Holland and the Republic of Ireland drew one-one","cn":"荷兰队和爱尔兰队打成了一比一平。"}},{"pos":"PHRASE 短语","cn":"结束;终止","en":"When an event or period of time draws to a close or draws to an end, it finishes.","ex":{"en":"Another celebration had drawn to its close.","cn":"又一场庆典结束了。"}},{"pos":"PHRASE 短语","cn":"(事件或时间)接近,临近","en":"If an event or period of time is drawing closer or is drawing nearer, it is approaching.","ex":{"en":"And all the time next spring's elections are drawing closer","cn":"明年春天的选举即将来临。"}},{"pos":"","cn":"","en":"to draw a blank→see: ; to draw breath→see: ; to draw someone's fire→see: ; to draw the line→see: ; to draw lots→see: ; the luck of the draw→see: ;"},{"pos":"","cn":"","en":"相关词组：draw in draw into draw off draw on draw out draw up draw upon"}]},"examples":[{"en":"The company has already drawn down €600 million of its €725 million credit line.","cn":"公司已从 7.25 亿欧元的授信额度中动用了 6 亿欧元。"},{"en":"The book starts slowly, but it gradually draws you in.","cn":"这本书开始时情节展开得很慢，但渐渐地就把你给完全吸引住了。"}]},"drank":{"lemma":"drink","media":{"uk":"media/uk/drank__gb_1.mp3","us":"media/us/drank__us_1.mp3"}},"drastically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extreme and sudden","cn":""},{"en":"drastic action/measures NATO threatened drastic action if its terms were not met. drastic cuts in government spending Drastic changes are needed if environmental catastrophe is to be avoided.","cn":""}]},"media":{"uk":"media/uk/drastically__gb_1.mp3","us":"media/us/drastically__us_1.mp3"},"oxford":{"phon":"ˈdræstɪkli","pos":"adverb","senses":[{"en":"in an extreme way that has a sudden, serious or violent effect on something","cn":"以一种极端的方式对某事物产生突然的、严重的或暴力的影响","ex":{"en":"Output has been drastically reduced.","cn":"产量急剧下降。"}}]}},"drive":{"media":{"uk":"media/uk/drive__gb_1.mp3","us":"media/us/drive__us_1.mp3"},"oxford":{"phon":"draɪv","pos":"verb","senses":[{"en":"to operate a vehicle so that it goes in a particular direction","cn":"驾驶；开车","g":"[intransitive, transitive]","lab":"British English","sc":"vehicle","ex":{"en":"Can you drive?","cn":"你会开车吗？"}},{"en":"to take somebody somewhere in a car, taxi, etc.","cn":"驾车送（人）","g":"[transitive]","sc":"vehicle","ex":{"en":"Could you drive me home?","cn":"你可以开车送我回家吗？"}},{"en":"to travel under the control of a driver","cn":"（在司机驾驶下）行驶","g":"[intransitive]","sc":"vehicle","ex":{"en":"A stream of black cars drove by.","cn":"一辆辆黑色汽车鱼贯驶过。"}},{"en":"to own or use a particular type of vehicle","cn":"拥有（或驾驶）…汽车","g":"[transitive]","sc":"vehicle","ex":{"en":"What car do you drive?","cn":"你开什么车？"}},{"en":"to make somebody very angry, crazy, etc. or to make them do something extreme","cn":"迫使（某人生气、发疯或做出极端事情）","g":"[transitive]","sc":"make somebody do something","ex":{"en":"to drive somebody crazy/mad/nuts/insane","cn":"把某人逼疯"}},{"en":"to force somebody to act in a particular way","cn":"迫使；驱使","g":"[transitive]","sc":"make somebody do something","ex":{"en":"The urge to survive drove them on.","cn":"求生的欲望驱使他们继续下去。"}},{"en":"to provide the power that makes a machine work; to operate a device","cn":"驱动；推动","g":"[transitive]","sc":"machine","ex":{"en":"a steam-driven locomotive","cn":"蒸汽机车"}},{"en":"to force somebody/something to move in a particular direction","cn":"驱赶；赶走；驱逐","g":"[transitive]","sc":"make somebody/something move","ex":{"en":"to drive sheep into a field","cn":"把羊群赶到田野里"}},{"en":"to influence something or cause it to make progress","cn":"激励；促进；推进","g":"[transitive]","sc":"cause something to make progress","ex":{"en":"This is the main factor driving investment in the area.","cn":"这是推动在这个地区投资的主要因素。"}},{"en":"to force something to go in a particular direction or into a particular position by pushing it, hitting it, etc.","cn":"击；打；敲；推","g":"[transitive]","sc":"hit/push","ex":{"en":"to drive a nail into a piece of wood","cn":"把钉子钉进一块木头"}},{"en":"to make an opening in or through something by using force","cn":"凿；挖掘","g":"[transitive]","sc":"make a hole","ex":{"en":"They drove a tunnel through the solid rock.","cn":"他们凿出一条穿过坚固岩石的隧道。"}},{"en":"to hit a ball with force, sending it forward","cn":"猛抽，猛击（球）","g":"[transitive, intransitive]","sc":"in sport","ex":{"en":"to drive the ball into the rough (= in golf)","cn":"将球击入长草区（高尔夫球）"}},{"en":"to carry something along","cn":"吹；卷；刮；冲","g":"[transitive]","sc":"wind/water","ex":{"en":"Huge waves drove the yacht onto the rocks.","cn":"巨浪将快艇冲到岩石上。"}},{"en":"to fall or move rapidly and with great force","cn":"猛落；急速驱进","g":"[intransitive]","sc":"wind/water","ex":{"en":"The waves drove against the shore.","cn":"波浪冲击着岸边。"}},{"en":"a journey in a car or other vehicle","cn":"驱车旅行；驾车路程","g":"[countable]","sc":"in/of vehicle","ex":{"en":"Let's go for a drive.","cn":"咱们开车去兜兜风吧。"},"pos":"noun"},{"en":"the equipment in a vehicle that takes power from the engine to the wheels","cn":"传动（或驱动）装置","g":"[countable, uncountable]","sc":"in/of vehicle","ex":{"en":"the drive shaft","cn":"驱动轴"},"pos":"noun"},{"en":"the position of the gears in a car with automatic transmission (= a system that changes the gears by itself so the driver does not have to) in which they are unlocked so that the engine can send power to the wheels","cn":"（汽车排挡的）前进挡","g":"[uncountable]","sc":"in/of vehicle","ex":{"en":"He jumped in, put the car in drive and set off.","cn":"他跳上车，挂上前进挡，出发了。"},"pos":"noun"},{"en":"a wide hard path or a private road that leads from the street to a house","cn":"（从街道通向住宅的宽阔或私人的）车道","g":"[countable]","sc":"outside house","ex":{"en":"There were two cars parked in the drive.","cn":"车道上停了两辆汽车。"},"pos":"noun"},{"en":"an organized effort by a group of people to achieve something","cn":"（团体为达到某目的而进行的）有组织的努力，运动","g":"[countable]","sc":"effort","ex":{"en":"The company is launching a big recruitment drive.","cn":"公司正在发起一场大规模的招聘活动。"},"pos":"noun"},{"en":"a strong desire or need in people","cn":"（人的）强烈欲望，本能需求","g":"[countable, uncountable]","sc":"desire/energy","ex":{"en":"The treatment should not affect your sex drive or fertility.","cn":"治疗不应影响您的性欲或生育能力。"},"pos":"noun"},{"en":"a strong desire to do things and achieve something; great energy","cn":"冲劲；干劲；精力","g":"[uncountable]","lab":"approving","sc":"desire/energy","ex":{"en":"He'll do very well—he has tremendous drive.","cn":"他会干得很出色的，他干劲十足。"},"pos":"noun"},{"en":"a long hard hit or kick","cn":"猛击；猛踢","g":"[countable]","sc":"in sport","ex":{"en":"She has a strong forehand drive (= in tennis).","cn":"她正手击球强而有力。"},"pos":"noun"},{"en":"a type of computer storage that stores large amounts of data on a spinning (= turning) disk","cn":"驱动器","g":"[countable]","sc":"computing","ex":{"en":"a CD drive","cn":"光盘驱动器"},"pos":"noun"},{"en":"a social occasion when a lot of people compete in a game such as whist or bingo","cn":"（惠斯特或宾戈纸牌游戏）比赛；玩纸牌的聚会","g":"[countable]","lab":"British English","sc":"games","pos":"noun"},{"en":"an act of going after animals or the enemy and making them go into a smaller area, especially in order to kill or capture them","cn":"驱赶；赶拢；（尤指）围攻，围歼","g":"[countable]","sc":"animals/enemy","pos":"noun"},{"en":"used in the names of roads","cn":"（用于路名）路，大道","sc":"road","ex":{"en":"21 Island Heights Drive","cn":"艾兰海茨路 21 号"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"驾驶;开车","en":"When you drive somewhere, you operate a car or other vehicle and control its movement and direction.","ex":{"en":"I drove into town and went to a restaurant for dinner","cn":"我驱车到市里一家餐馆就餐。"}},{"pos":"VERB 动词","cn":"驾车送(人)","en":"If you drive someone somewhere, you take them there in a car or other vehicle.","ex":{"en":"His daughter Carly drove him to the train station.","cn":"他女儿卡莉开车将他送到火车站。"}},{"pos":"N-COUNT 可数名词","cn":"驱车旅行;驾车路程","en":"A drive is a journey in a car or other vehicle.","ex":{"en":"I thought we might go for a drive on Sunday.","cn":"我想星期天我们可以驱车旅行。"}},{"pos":"N-COUNT 可数名词","cn":"(从马路通往住宅的宽阔)车道","en":"A drive is a wide piece of hard ground, or sometimes a private road, that leads from the road to a person's house."},{"pos":"VERB 动词","cn":"驱动;推动","en":"If something drives a machine, it supplies the power that makes it work.","ex":{"en":"The current flows into electric motors that drive the wheels.","cn":"电流流入了驱动车轮的电动机。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"传动力;驱动力","en":"Drive is the power supplied by the engine to particular wheels in a car or other vehicle to make the vehicle move.","ex":{"en":"He put the jeep in four-wheel drive and splashed up the slope.","cn":"他将吉普车切换为四轮驱动模式后涉水爬上了坡。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机的）驱动器","en":"You use drive to refer to the mechanical part of a computer which reads the data on disks and tapes, or writes data onto them.","ex":{"en":"...equipment such as terminals, tape drives or printers.","cn":"诸如电脑终端、磁带驱动器或打印机等的设备"}},{"pos":"VERB 动词","cn":"击;打;敲;推","en":"If you drive something such as a nail into something else, you push it in or hammer it in using a lot of effort.","ex":{"en":"I used a sledgehammer to drive the pegs into the ground","cn":"我用一把大锤子把短桩打进地里。"}},{"pos":"VERB 动词","cn":"用力击(球);用力踢(球)","en":"In games such as cricket, golf, or football, if a player drives a ball somewhere, they kick or hit it there with a lot of force.","ex":{"en":"Armstrong drove the ball into the roof of the net.","cn":"阿姆斯特朗将球打入球门网顶。"}},{"pos":"N-COUNT 可数名词","cn":"(高尔夫球的)开球","en":"In golf, a drive is the first stroke a player makes from the tee.","ex":{"en":"Woosnam sliced his drive into the bushes.","cn":"伍斯纳姆的开杆球打进了灌木丛中。"}},{"pos":"VERB 动词","cn":"(风、雨或雪朝某个方向)吹,卷,刮,冲","en":"If the wind, rain, or snow drives in a particular direction, it moves with great force in that direction.","ex":{"en":"Rain drove against the window.","cn":"雨敲打着窗户。"}},{"pos":"VERB 动词","cn":"驱赶;驱逐;赶走","en":"If you drive people or animals somewhere, you make them go to or from that place.","ex":{"en":"The last offensive drove thousands of people into Thailand","cn":"最后一次进攻将成千上万的人赶到了泰国。"}},{"pos":"VERB 动词","cn":"迫使;逼迫","en":"To drive someone into a particular state or situation means to force them into that state or situation.","ex":{"en":"The recession and hospital bills drove them into bankruptcy","cn":"经济衰退和医疗账单逼得他们破产了。"}},{"pos":"VERB 动词","cn":"驱使，迫使(某人做出极端的事情)","en":"The desire or feeling that drives a person to do something, especially something extreme, is the desire or feeling that causes them to do it.","ex":{"en":"More than once, depression drove him to attempt suicide","cn":"抑郁症使他不止一次地企图自杀。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精力;干劲;冲劲;决心","en":"If you say that someone has drive, you mean they have energy and determination.","ex":{"en":"John will be best remembered for his drive and enthusiasm.","cn":"约翰的魄力和热情最令人难忘。"}},{"pos":"N-COUNT 可数名词","cn":"强烈欲望;强烈需求;本能需求","en":"A drive is a very strong need or desire in human beings that makes them act in particular ways.","ex":{"en":"...compelling, dynamic sex drives.","cn":"强烈而旺盛的性欲"}},{"pos":"N-SING 单数名词","cn":"(为达到某目的而进行的)努力,运动","en":"A drive is a special effort made by a group of people for a particular purpose.","ex":{"en":"The ANC is about to launch a nationwide recruitment drive","cn":"非洲国民大会打算在全国范围内发起招募运动。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于路名)路,大道","en":"Drive is used in the names of some streets.","ex":{"en":"...23 Queen's Drive, Malvern, Worcestershire.","cn":"伍斯特郡,莫尔文市,女王大道 23 号"}},{"pos":"PHRASE 短语","cn":"意欲所指;暗示","en":"If you ask someone what they are driving at, you are asking what they are trying to say or what they are saying indirectly.","ex":{"en":"It was clear Cohen didn't understand what Millard was driving at.","cn":"看得出科恩并不明白米勒德想说什么。"}},{"pos":"","cn":"","en":"to drive a hard bargain→see: ;"},{"pos":"","cn":"","en":"相关词组：drive away drive off drive out"}]},"examples":[{"en":"This is the main factor driving investment in the area.","cn":"这是推动在这个地区投资的主要因素。"},{"en":"He scored with a brilliant 25-yard drive.","cn":"他在 25 码外一脚劲射入球得分。"}]},"dropout":{"media":{"uk":"media/uk/dropout__gb_1.mp3","us":"media/us/dropout__us_1.mp3"},"oxford":{"phon":"ˈdrɒpaʊt","pos":"noun","senses":[{"en":"a person who leaves school or college before they have finished their studies","cn":"辍学者；退学者","ex":{"en":"college dropouts","cn":"大学肄业生"}},{"en":"a person who rejects the ideas and ways of behaving that are accepted by the rest of society","cn":"拒绝传统社会的人","ex":{"en":"He’s a dropout who will never have a steady job.","cn":"他是一个辍学者，永远不会有稳定的工作。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"离经叛道者;摈弃社会习俗者","en":"If you describe someone as a drop-out, you disapprove of the fact that they have rejected the accepted ways of society, for example by not having a regular job."},{"pos":"N-COUNT 可数名词","cn":"辍学者;退学者","en":"A drop-out is someone who has left school or college before they have finished their studies.","ex":{"en":"...high-school drop-outs.","cn":"中学退学者"}},{"pos":"ADJ 形容词","cn":"退学的;辍学的;中途放弃的","en":"If you refer to the drop-out rate, you are referring to the number of people who leave a school or college early, or leave a course or other activity before they have finished it.","ex":{"en":"The drop-out rate among students is currently one in three.","cn":"现在学生的辍学率是三分之一。"}}]},"examples":[{"en":"a university with a high dropout rate","cn":"退学率高的大学"},{"en":"college dropouts","cn":"大学肄业生"}]},"drum":{"media":{"uk":"media/uk/drum__gb_1.mp3","us":"media/us/drum__us_1.mp3"},"oxford":{"phon":"drʌm","pos":"noun","senses":[{"en":"a musical instrument made of a hollow round frame with plastic or skin stretched tightly across one or both ends. You play it by hitting it with sticks or with your hands.","cn":"鼓","ex":{"en":"to play the drum","cn":"击鼓"}},{"en":"a large container for oil or chemicals that is like a cylinder in shape","cn":"（装油或化学剂的）大桶","ex":{"en":"a 50 gallon drum","cn":"容积为 50 加仑的桶"}},{"en":"a thing that is like a drum in shape, especially part of a machine","cn":"鼓状物；（尤指机器上的）鼓轮，滚筒","ex":{"en":"The mixture flows to a revolving drum where the water is filtered out.","cn":"混合剂流过旋转着的滚筒时水分便从中滤出。"}},{"en":"to play a drum","cn":"打鼓；击鼓","g":"[intransitive]","ex":{"en":"Then they started chanting and drumming and stamping their feet.","cn":"然后他们开始吟唱、击鼓、跺脚。"},"pos":"verb"},{"en":"to make a sound by hitting a surface again and again","cn":"连续敲击…使发出咚咚声；不停地击打","g":"[transitive, intransitive]","ex":{"en":"Impatiently, she drummed her fingers on the table.","cn":"她不耐烦地用手指敲着桌子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼓","en":"A drum is a musical instrument consisting of a skin stretched tightly over a round frame. You play a drum by beating it with sticks or with your hands."},{"pos":"N-COUNT 可数名词","cn":"(装油等的)鼓状容器,圆桶","en":"A drum is a large cylindrical container which is used to store fuel or other substances.","ex":{"en":"...an oil drum.","cn":"油桶"}},{"pos":"N-COUNT 可数名词","cn":"(机器上的)鼓状物,鼓轮,滚筒","en":"A drum is a hollow cylindrical structure which is part of a machine, for example a washing machine."},{"pos":"N-COUNT 可数名词","cn":"（缠绕电线或绳索的）卷筒,转筒","en":"A drum is a circular object on which wire or rope is wound and kept.","ex":{"en":"He had found a drum of electric cable.","cn":"他发现了一卷电缆。"}},{"pos":"V-ERG 及物/不及物动词","cn":"有规律地敲击（使发出连续的击打声）","en":"If something drums on a surface, or if you drum something on a surface, it hits it regularly, making a continuous beating sound.","ex":{"en":"He drummed his fingers on the leather top of his desk","cn":"他用手指连续敲击他的皮革桌面。"}},{"pos":"PHRASE 短语","cn":"竭力鼓吹;摇旗呐喊","en":"If someone beats the drum or bangs the drum for something, they support it strongly.","ex":{"en":"The trade secretary disagreed but promised to 'bang the drum for industry'.","cn":"贸易部长并不同意，但是答应会“为产业界摇旗呐喊”。"}},{"pos":"","cn":"","en":"相关词组：drum into drum out drum up"}]},"examples":[{"en":"He had flown to the north of the country to drum up support for the campaign.","cn":"他已乘飞机到国家的北方去努力争取对这一运动的支持。"},{"en":"The mixture flows to a revolving drum where the water is filtered out.","cn":"混合剂流过旋转着的滚筒时水分便从中滤出。"}]},"dres":{"oxford":{"phon":"","pos":"abbr.","senses":[{"en":"(in writing) Doctor （","cn":"书写形式）医生，博士"},{"en":"(in street names) drive （","cn":"用于街道名）路，大道"}]}},"driveways":{"lemma":"driveway","media":{"uk":"media/uk/driveway__gb_1.mp3","us":"media/us/driveway__us_1.mp3"}},"drowsily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wanting to sleep very soon, so that your eyes start to close","cn":""},{"en":"starting to sleep because you are in a warm place, have drunk too much alcohol, or have taken medicine","cn":""}]},"examples":[{"en":"The drug can make you drowsy.","cn":"","src":"ld"},{"en":"a drowsy summer afternoon","cn":"","src":"ld"}],"media":{"uk":"media/uk/drowsily__gb_1.mp3","us":"media/us/drowsily__us_1.mp3"},"oxford":{"phon":"ˈdraʊzɪli","pos":"adverb","senses":[{"en":"in a tired way, as if you want to sleep","cn":"困倦地：疲倦地，好像你想睡着","ex":{"en":"She yawned drowsily.","cn":"她昏昏欲睡地打了个哈欠。"}}]}},"driving":{"media":{"uk":"media/uk/driving__gb_1.mp3","us":"media/us/driving__us_1.mp3"},"oxford":{"phon":"ˈdraɪvɪŋ","pos":"noun","senses":[{"en":"the way that somebody drives a vehicle; the act of driving","cn":"行车的方式；驾驶；行车","lab":"British English","ex":{"en":"She was convicted of dangerous driving.","cn":"她被判危险驾驶罪。"}},{"en":"strong and powerful; having a strong influence in making something happen","cn":"强有力的；起推动作用的；推动的","ex":{"en":"Who was the driving force (= the person with the strongest influence) in the band?","cn":"谁是乐队的主力？"},"pos":"adjective"},{"en":"falling very fast and at an angle","cn":"猛烈的；倾泻而下的","ex":{"en":"a day of strong winds and driving rain","cn":"狂风大雨的一天"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"推动的;推进的;强有力的","en":"The driving force or idea behind something that happens or is done is the main thing that has a strong effect on it and makes it happen or be done in a particular way.","ex":{"en":"Consumer spending was the driving force behind the economic growth in the summer","cn":"顾客消费是夏季经济增长的强大推动力。"}}]},"examples":[{"en":"Who was the driving force (= the person with the strongest influence) in the band?","cn":"谁是乐队的主力？"},{"en":"dangerous driving","cn":"危险驾驶"}],"base":"drive"},"drape":{"media":{"uk":"media/uk/drape__gb_1.mp3","us":"media/us/drape__us_1.mp3"},"oxford":{"phon":"dreɪp","pos":"verb","senses":[{"en":"to hang clothes, materials, etc. loosely on somebody/something","cn":"将（衣服、织物等）悬挂，披","g":"[transitive]","ex":{"en":"She had a shawl draped around her shoulders.","cn":"她肩上披着一条围巾。"}},{"en":"to hang loosely","cn":"垂下；悬垂","g":"[intransitive]","ex":{"en":"Some silk fabrics will drape beautifully.","cn":"有些丝绸面料垂感优美。"}},{"en":"to cover or decorate somebody/something with material","cn":"遮盖；盖住；装饰","g":"[transitive]","ex":{"en":"walls draped in ivy","cn":"长满常春藤的墙"}},{"en":"to allow part of your body to rest on something in a relaxed way","cn":"使（身体部位）放松地搭在…上","g":"[transitive]","ex":{"en":"His arm was draped casually around her shoulders.","cn":"他随意地将手臂搭在她的双肩上。"}},{"en":"a long thick curtain","cn":"（厚长的）帘子，帷帘，帷幕","ex":{"en":"blue velvet drapes","cn":"蓝色丝绒帷帘"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"将(织物)悬挂;披","en":"If you drape a piece of cloth somewhere, you place it there so that it hangs down in a casual and graceful way.","ex":{"en":"Natasha took the coat and draped it over her shoulders","cn":"娜塔莎拿起外套披在肩上。"}},{"pos":"VERB 动词","cn":"遮盖;盖住","en":"If someone or something is draped in a piece of cloth, they are loosely covered by it.","ex":{"en":"The coffin had been draped in a Union Jack","cn":"灵柩上覆盖着英国国旗。"}},{"pos":"VERB 动词","cn":"将(身体的某部位)随意搭在…上","en":"If you drape a part of your body somewhere, you lay it there in a relaxed and graceful way.","ex":{"en":"Nicola slowly draped herself across the couch","cn":"妮古拉慢慢地靠在了长沙发上。"}},{"pos":"N-COUNT 可数名词","cn":"(厚的)帘子，帷幕","en":"Drapes are pieces of heavy fabric that you hang from the top of a window and can close to keep the light out or stop people looking in.","ex":{"en":"He pulled the drapes shut, locked the door behind him.","cn":"他把帘子拉严，转身把门锁好。"}}]},"examples":[{"en":"His arm was draped casually around her shoulders.","cn":"他随意地将手臂搭在她的双肩上。"},{"en":"He draped his coat over the back of the chair.","cn":"他把外衣搭在座椅背上。"}]},"dreadfully":{"media":{"uk":"media/uk/dreadfully__gb_1.mp3","us":"media/us/dreadfully__us_1.mp3"},"oxford":{"phon":"ˈdredfəli","pos":"adverb","senses":[{"en":"extremely; very much","cn":"极端；非常；极其","ex":{"en":"I'm dreadfully sorry.","cn":"我感到非常抱歉。"}},{"en":"very badly","cn":"厉害地；严重地；极糟糕地","ex":{"en":"They suffered dreadfully during the war.","cn":"他们在战争中遭受了巨大的痛苦。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糟糕透顶的;令人不快的;劣质的","en":"If you say that something is dreadful, you mean that it is very bad or unpleasant, or very poor in quality.","ex":{"en":"They told us the dreadful news","cn":"他们告诉了我们那糟糕透顶的消息。"}},{"pos":"ADJ 形容词","cn":"极严重的","en":"Dreadful is used to emphasize the degree or extent of something bad.","ex":{"en":"We've made a dreadful mistake","cn":"我们犯了个极大的错误。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(看上去或感觉到)病得不轻的,极度疲惫的,非常沮丧的","en":"If someone looks or feels dreadful, they look or feel very ill, tired, or upset.","ex":{"en":"Are you all right? You look dreadful","cn":"你还好吧？你看上去十分疲惫。"}}]},"examples":[{"en":"They suffered dreadfully during the war.","cn":"他们在战争中遭受了巨大的痛苦。"},{"en":"I'm dreadfully sorry.","cn":"我感到非常抱歉。"}]},"drug":{"media":{"uk":"media/uk/drug__gb_1.mp3","us":"media/us/drug__us_1.mp3"},"oxford":{"phon":"drʌɡ","pos":"noun","senses":[{"en":"an illegal substance that some people smoke, inject, etc. for the physical and mental effects it has","cn":"毒品","lab":"informal","ex":{"en":"He does not smoke or take drugs.","cn":"他既不抽烟也不吸毒。"}},{"en":"a substance used as a medicine or used in a medicine","cn":"药；药物","lab":"British English","ex":{"en":"to prescribe/administer a drug","cn":"开药；给药"}},{"en":"to give a person or an animal a drug, especially to make them unconscious, or to affect their performance in a race or competition","cn":"使服麻醉药；用药麻醉；使服兴奋剂","ex":{"en":"He was drugged and bundled into the back of the car.","cn":"他被麻醉后塞入汽车后座。"},"pos":"verb"},{"en":"to add a drug to somebody’s food or drink to make them unconscious or sleepy","cn":"（在食物或饮料中）投放麻醉药，下麻醉药","ex":{"en":"Her drink must have been drugged.","cn":"她的饮料中肯定被掺了麻醉药。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"药;药物;药品","en":"A drug is a chemical which is given to people in order to treat or prevent an illness or disease.","ex":{"en":"The drug will be useful to hundreds of thousands of infected people.","cn":"这种药将惠及成千上万的感染者。"}},{"pos":"N-COUNT 可数名词","cn":"毒品","en":"Drugs are substances that some people take because of their pleasant effects, but which are usually illegal.","ex":{"en":"His mother was on drugs, on cocaine","cn":"他母亲吸毒，吸可卡因。"}},{"pos":"VERB 动词","cn":"将…麻醉;给…服麻醉剂","en":"If you drug a person or animal, you give them a chemical substance in order to make them sleepy or unconscious.","ex":{"en":"They drugged the guard dog with doped meatballs","cn":"他们用掺了麻醉药的肉丸子麻醉了看门狗。"}},{"pos":"VERB 动词","cn":"往（食物或饮料中）投放麻醉药","en":"If food or drink is drugged, a chemical substance is added to it in order to make someone sleepy or unconscious when they eat or drink it.","ex":{"en":"I wonder now if that drink had been drugged","cn":"我现在想那饮料是否被人动过手脚。"}}]},"examples":[{"en":"Drugs have been seized with a street value of two million dollars.","cn":"黑市价值二百万元的毒品已被查获。"},{"en":"a hard (= very harmful) drug such as heroin","cn":"海洛因之类的硬毒品（毒性很大）"}]},"draft":{"oxford":{"phon":"drɑːft","pos":"noun","senses":[{"en":"a rough written version of something that is not yet in its final form","cn":"草稿；草案；草图","g":"[countable]","ex":{"en":"This is only the first draft of my speech.","cn":"这只是我演讲的初稿。"}},{"en":"a written order to a bank to pay money to somebody","cn":"汇票","g":"[countable]","lab":"finance","ex":{"en":"Payment must be made by bank draft drawn on a UK bank.","cn":"付款必须用英国银行承兑的汇票。"}},{"en":"the practice of ordering people by law to join the armed forces","cn":"征募；征兵","g":"[singular]","lab":"especially US English"},{"en":"a system in which professional teams in some sports choose players each year from among college students","cn":"选秀，运动员选拔制（某些职业运动队每年在大学生中选拔新队员）","g":"[singular]","lab":"North American English","ex":{"en":"He was the fourth player chosen in the 2017 draft, but the first of his class to reach the major leagues.","cn":"他是 2017 年选秀中第四名被选中的球员，却成为同届第一个进入大联盟的球员。"}},{"en":"a flow of cool air in a room or other small space","cn":"穿堂风；通风气流；通风","g":"[countable]","lab":"North American English","ex":{"en":"Can you shut the door? There's a draft in here.","cn":"你关上门好吗？这里有穿堂风。"}},{"en":"one continuous action of swallowing liquid (= making it go down your throat); the amount swallowed","cn":"一饮（的量）","g":"[countable]","lab":"North American English","ex":{"en":"He took a deep draft of his beer.","cn":"他深深地喝了一口啤酒。"}},{"en":"medicine in a liquid form","cn":"药水；饮剂","g":"[countable]","lab":"North American English","ex":{"en":"a sleeping draft (= one that makes you sleep)","cn":"安眠药"}},{"en":"to write the first rough version of something such as a letter, speech, book or law","cn":"起草；草拟","ex":{"en":"I'll draft a letter for you.","cn":"我来为你草拟一封信。"},"pos":"verb"},{"en":"to choose people and send them somewhere for a special task","cn":"选派；抽调","ex":{"en":"Extra police are being drafted in to control the crowds.","cn":"现正在另外抽调警察去控制人群。"},"pos":"verb"},{"en":"to order somebody by law to join the armed forces","cn":"征募；征召","g":"[usually passive]","lab":"North American English","ex":{"en":"They were drafted into the army.","cn":"他们应征入伍。"},"pos":"verb"},{"en":"served from a large container (= a barrel) rather than in a bottle","cn":"零售的；散装的","g":"[usually before noun]","ex":{"en":"draft beer","cn":"桶装啤酒。"},"pos":"adjective"},{"en":"used for pulling heavy loads","cn":"拖曳重载用的","g":"[only before noun]","ex":{"en":"a draft horse","cn":"拉车的马，役马。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"草稿;草案;草图","en":"A draft is an early version of a letter, book, or speech.","ex":{"en":"I rewrote his rough draft, which was published under my name","cn":"我把他的草稿重新改写，并以我的名字发表了。"}},{"pos":"VERB 动词","cn":"起草;草拟","en":"When you draft a letter, book, or speech, you write the first version of it.","ex":{"en":"He drafted a standard letter to the editors","cn":"他起草了一份给编辑的标准信函。"}},{"pos":"VERB 动词","cn":"征召…入伍","en":"If you are drafted, you are ordered to serve in the armed forces, usually for a limited period of time.","ex":{"en":"During the Second World War, he was drafted into the US Army","cn":"二战期间，他应征加入了美国陆军。"}},{"pos":"VERB 动词","cn":"选派;抽调;派遣","en":"If people are drafted into a place, they are moved there to do a particular job.","ex":{"en":"Extra police have been drafted into the town after the violence","cn":"暴乱过后又有警力被抽调到了该镇。"}},{"pos":"N-SING 单数名词","cn":"（通常指短期的）征兵，征召","en":"The draft is the practice of ordering people to serve in the armed forces, usually for a limited period of time.","ex":{"en":"...his effort to avoid the draft.","cn":"他试图逃避兵役"}},{"pos":"N-COUNT 可数名词","cn":"汇票","en":"A draft is a written order for payment of money by a bank, especially from one bank to another.","ex":{"en":"The money was payable by a draft drawn by the home","cn":"这笔钱可凭国内承兑的汇票支付。"}}]},"media":{"uk":"media/uk/draft__gb_1.mp3","us":"media/us/draft__us_1.mp3"},"examples":[{"en":"Payment must be made by bank draft drawn on a UK bank.","cn":"付款必须用英国银行承兑的汇票。"},{"en":"Extra police are being drafted in to control the crowds.","cn":"现正在另外抽调警察去控制人群。"}]},"drafts":{"lemma":"draft"},"drugstore":{"media":{"uk":"media/uk/drugstore__gb_1.mp3","us":"media/us/drugstore__us_1.mp3"},"oxford":{"phon":"ˈdrʌɡstɔː(r)","pos":"noun","senses":[{"en":"a shop that sells medicines and also other types of goods, for example cosmetics","cn":"（兼售化妆品等的）药房","ex":{"en":"I bought these sunglasses at the drugstore.","cn":"我在药店买了这副太阳镜。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美国兼售化妆品、家居用品、饮料、小吃等的)药店,药房","en":"In the United States, a drugstore is a shop where drugs and medicines are sold or given out, and where you can buy cosmetics, some household goods, and also drinks and snacks. →see usage note at:"}]}},"drugs":{"lemma":"drug","media":{"uk":"media/uk/drug__gb_1.mp3","us":"media/us/drug__us_1.mp3"}},"drawn":{"media":{"uk":"media/uk/drawn__gb_2.mp3","us":"media/us/drawn__us_2.mp3"},"oxford":{"phon":"drɔːn","pos":"adjective","senses":[{"en":"looking pale and thin because the person is ill, tired or worried","cn":"（因身体不适、疲倦或忧虑）憔悴的，苍白的","ex":{"en":"She looked very pale and drawn.","cn":"她看上去脸色苍白，憔悴不堪。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Drawn is the past participle of draw ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或人脸)清瘦的,憔悴的,愁眉苦脸的","en":"If someone or their face looks drawn, their face is thin and they look very tired, ill, worried, or unhappy.","ex":{"en":"She looked drawn and tired when she turned towards me.","cn":"她转向我时看上去憔悴又疲惫。"}}]},"base":"draw"},"drinking":{"media":{"uk":"media/uk/drinking__gb_1.mp3","us":"media/us/drinking__us_1.mp3"},"oxford":{"phon":"ˈdrɪŋkɪŋ","pos":"noun","senses":[{"en":"the act of drinking alcohol","cn":"喝酒；饮酒","ex":{"en":"Drinking is not advised during pregnancy.","cn":"建议妊娠期不要饮酒。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"喜欢饮酒的;经常饮酒的;贪杯的","en":"Someone's drinking friends or companions are people they regularly drink alcohol with."}]},"examples":[{"en":"Drinking is not advised during pregnancy.","cn":"建议妊娠期不要饮酒。"},{"en":"There are tough penalties for drinking and driving.","cn":"酒后驾车刑罚很重。"}],"base":"drink"},"drawing":{"media":{"uk":"media/uk/drawing__gb_1.mp3","us":"media/us/drawing__us_1.mp3"},"oxford":{"phon":"ˈdrɔːɪŋ","pos":"noun","senses":[{"en":"a picture made using a pencil or pen rather than paint","cn":"图画；素描画","g":"[countable]","lab":"US English","ex":{"en":"a pencil/pen-and-ink/charcoal drawing","cn":"铅笔画；钢笔画；炭画"}},{"en":"the art or skill of making pictures, plans, etc. using a pen or pencil","cn":"绘画（艺术）；制图（技巧）","g":"[uncountable]","ex":{"en":"I'm not very good at drawing.","cn":"我不擅长绘画。"}},{"en":"the act of choosing something, for example the winner of a prize or the teams who play each other in a competition, usually by taking pieces of paper, etc. out of a container without being able to see what is written on them","cn":"抽彩；抽奖；抽签","g":"[usually singular]","lab":"North American English"},{"en":"a competition in which the winners are chosen in a drawing","cn":"抽奖","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"素描（画）；图画","en":"A drawing is a picture made with a pencil or pen.","ex":{"en":"She did a drawing of me.","cn":"她给我画了张像。"}}]},"examples":[{"en":"He did/made a drawing of the old farmhouse.","cn":"他画了一幅古老农舍的素描。"},{"en":"I'm not very good at drawing.","cn":"我不擅长绘画。"}],"base":"draw"},"drunk":{"media":{"uk":"media/uk/drunk__gb_2.mp3","us":"media/us/drunk__us_2.mp3"},"oxford":{"phon":"drʌŋk","pos":"adjective","senses":[{"en":"having drunk so much alcohol that it is impossible to think or speak clearly","cn":"（酒）醉","g":"[not usually before noun]","ex":{"en":"They were clearly too drunk to drive.","cn":"他们显然喝得太醉了，无法开车。"}},{"en":"very excited, tired, etc. because of a particular emotion or situation","cn":"陶醉；沉醉；飘飘然；忘乎所以","lab":"formal","ex":{"en":"drunk with success","cn":"因成功而飘飘然"}},{"en":"a person who is drunk or who often gets drunk","cn":"醉汉；酒鬼；酗酒者","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喝醉的","en":"Someone who is drunk has drunk so much alcohol that they cannot speak clearly or behave sensibly.","ex":{"en":"Stewart could not remember exactly why he had done it because he was so drunk","cn":"斯图尔特记不清他为什么要那样做了,因为他烂醉如泥。"}},{"pos":"N-COUNT 可数名词","cn":"醉汉,酒鬼;酗酒者","en":"A drunk is someone who is drunk or frequently gets drunk.","ex":{"en":"A drunk lay in the alley.","cn":"一个酒鬼躺在小胡同里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陶醉的;兴奋的;沉醉的","en":"If you are drunk with a strong emotion or an experience, you are in a state of great excitement because of it.","ex":{"en":"They are currently drunk with success","cn":"他们现在正陶醉于成功之中。"}},{"pos":"","cn":"","en":"Drunk is the past participle of drink."}]},"examples":[{"en":"She was too drunk to remember anything about the party.","cn":"她喝得酩酊大醉，聚会上的事什么都记不得了。"},{"en":"His only way of dealing with his problems was to go out and get drunk.","cn":"他解决烦心事的唯一办法就是出去喝个烂醉。"}],"base":"drink"},"drop":{"media":{"uk":"media/uk/drop__gb_1.mp3","us":"media/us/drop__us_1.mp3"},"oxford":{"phon":"drɒp","pos":"verb","senses":[{"en":"to allow something to fall by accident; to fall by accident","cn":"（意外地）落下，掉下，使落下","g":"[transitive, intransitive]","lab":"figurative","sc":"fall","ex":{"en":"Be careful not to drop that plate.","cn":"小心别把那盘子摔了。"}},{"en":"to make something fall deliberately; to let yourself fall","cn":"扔下；投下；（故意）落下；倒下","g":"[transitive, intransitive]","lab":"British English","sc":"fall","ex":{"en":"You can never be sure whether the planes will be dropping bombs or food parcels.","cn":"永远无法确定飞机投掷的是炸弹还是食物包。"}},{"en":"to fall down or be no longer able to stand because you are extremely tired","cn":"累倒；累垮","g":"[intransitive]","lab":"informal","sc":"fall","ex":{"en":"I feel ready to drop.","cn":"我感到快累垮了。"}},{"en":"to become or make something weaker, lower or less","cn":"（使）变弱，降低，减少","g":"[intransitive, transitive]","sc":"become weaker/less","ex":{"en":"The temperature has dropped considerably.","cn":"温度已大大降低。"}},{"en":"to fail to win something","cn":"没得到；失去","g":"[transitive]","sc":"in sport","ex":{"en":"It's a long time since we dropped a game.","cn":"我们已经很久没有输过比赛了。"}},{"en":"to look down","cn":"垂下（眼睛）；垂视","g":"[intransitive, transitive]","lab":"formal","sc":"eyes","ex":{"en":"Her eyes dropped to her lap.","cn":"她双目低垂，看着自己的腿。"}},{"en":"to slope steeply downwards","cn":"急剧倾斜而下","g":"[intransitive]","sc":"slope downwards","ex":{"en":"In front of them the valley dropped sharply away from the road.","cn":"他们前面的山谷从路旁急剧倾斜而下。"}},{"en":"to stop so that somebody can get out of a car, etc.; to deliver or leave something in a particular place, especially on the way to somewhere else","cn":"中途卸客；中途卸货","g":"[transitive]","sc":"deliver/send","ex":{"en":"Can you drop me near the bank?","cn":"你可以让我在银行附近下车吗？"}},{"en":"to send a short letter or email to somebody","cn":"寄，送，写（信）","g":"[transitive]","sc":"deliver/send","ex":{"en":"Drop me a line when you get there.","cn":"你到那儿后给我写封信。"}},{"en":"to put some text, an icon, etc. into a file, folder or place on a computer screen, using the mouse","cn":"（用鼠标）把（文本、图标等）放下","g":"[transitive]","sc":"on a computer screen","ex":{"en":"You can easily drag and drop files onto your memory stick.","cn":"你可以轻松地把文件拖放到记忆棒里。"}},{"en":"to leave somebody/something out by accident or deliberately","cn":"遗漏；省略；不予考虑","g":"[transitive]","sc":"leave out","ex":{"en":"She's been dropped from the team because of injury.","cn":"她因受伤而未被列入队员名单。"}},{"en":"to stop seeing somebody socially","cn":"不再与（某人）往来；同（某人）断绝联系","g":"[transitive]","sc":"friends","ex":{"en":"She's dropped most of her old friends.","cn":"她已与多数老朋友停止了来往。"}},{"en":"to stop doing or discussing something; to not continue with something","cn":"停止；终止；放弃","g":"[transitive]","sc":"stop","ex":{"en":"I dropped German (= stopped studying it) when I was 14.","cn":"我 14 岁后就没再学德语。"}},{"en":"to say or do something in order to show somebody, in an indirect way, what you are thinking","cn":"暗示；透露","g":"[transitive]","sc":"hint"},{"en":"to be made available to the public","cn":"发布；发行","g":"[intransitive]","lab":"informal","sc":"music, etc.","ex":{"en":"A new episode drops every Monday.","cn":"每周一都会推出新剧集。"}},{"en":"to let a stitch go off the needle","cn":"漏，脱，掉（针）","g":"[transitive]","sc":"in knitting"},{"en":"a very small amount of liquid that forms a round shape","cn":"滴；水珠","g":"[countable]","sc":"of liquid","ex":{"en":"The first drops of rain fell.","cn":"最初的几滴雨落了下来。"},"pos":"noun"},{"en":"a small quantity of a liquid","cn":"少量；微量；一点点","g":"[countable, usually singular]","sc":"of liquid","ex":{"en":"Could I have a drop more milk in my coffee, please?","cn":"请给我在咖啡里多加点牛奶好吗？"},"pos":"noun"},{"en":"a fall or reduction in the amount, level or number of something","cn":"下降；下跌；减少","g":"[countable, usually singular]","sc":"fall","ex":{"en":"a sharp/steep drop in profits","cn":"利润急剧下降"},"pos":"noun"},{"en":"a distance straight down from a high point to a lower point","cn":"下落的距离；落差","g":"[countable, usually singular]","sc":"distance down","ex":{"en":"There was a sheer drop of fifty metres to the rocks below.","cn":"距下面的岩石有五十米的垂直距离。"},"pos":"noun"},{"en":"a liquid medicine that you put one drop at a time into your eyes, ears or nose","cn":"滴剂","g":"[plural]","sc":"medicine","ex":{"en":"eye drops","cn":"眼药水"},"pos":"noun"},{"en":"the act of delivering somebody/something in a vehicle or by plane; the act of dropping something","cn":"运送；空投","g":"[countable]","sc":"delivering","ex":{"en":"Aid agencies are organizing food drops to civilians in the war zone.","cn":"援助机构正组织向战区平民运送食品。"},"pos":"noun"},{"en":"a small round sweet of the type mentioned","cn":"糖豆；糖粒；糖块","g":"[countable]","sc":"sweet/candy","ex":{"en":"fruit drops","cn":"水果糖"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）降低;（使）下降;（使）减少","en":"If a level or amount drops or if someone or something drops it, it quickly becomes less.","ex":{"en":"Temperatures can drop to freezing at night","cn":"夜间温度可能会降到零度以下。"}},{"pos":"VERB 动词","cn":"(意外地)使掉下,使落下","en":"If you drop something, you accidentally let it fall.","ex":{"en":"I dropped my glasses and broke them.","cn":"我不小心把眼镜掉下来摔碎了。"}},{"pos":"VERB 动词","cn":"掉到…上;从…上掉落","en":"If something drops onto something else, it falls onto that thing. If something drops from somewhere, it falls from that place.","ex":{"en":"He felt hot tears dropping onto his fingers","cn":"他感觉到热泪掉到他的手指上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"投下;丢下;扔下;掉下","en":"If you drop something somewhere or if it drops there, you deliberately let it fall there.","ex":{"en":"Drop the noodles into the water","cn":"将面条下到水里。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(疲惫地)垂下,低垂,垂落","en":"If a person or a part of their body drops to a lower position, or if they drop a part of their body to a lower position, they move to that position, often in a tired and lifeless way.","ex":{"en":"Nancy dropped into a nearby chair","cn":"南希疲惫地瘫坐到近处的椅子上。"}},{"pos":"VERB 动词","cn":"累倒;累垮","en":"To drop is used in expressions such as to be about to drop and to dance until you drop to emphasize that you are exhausted and can no longer continue doing something.","ex":{"en":"She looked about to drop","cn":"她看上去快要累垮了。"}},{"pos":"VERB 动词","cn":"(开玩笑或不雅地)脱掉（裤子）","en":"If a man drops his trousers, he pulls them down, usually as a joke or to be rude.","ex":{"en":"A couple of boozy revellers dropped their trousers.","cn":"两名醉酒的狂欢者脱掉了他们的裤子。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(声音)降低,压低","en":"If your voice drops or if you drop your voice, you speak more quietly.","ex":{"en":"Her voice will drop to a dismissive whisper","cn":"她会把声音压低，轻蔑地低语。"}},{"pos":"VERB 动词","cn":"中途放下（某人）;中途卸下（某物）","en":"If you drop someone or something somewhere, you take them somewhere and leave them there, usually in a car or other vehicle.","ex":{"en":"He dropped me outside the hotel","cn":"他把我送到了酒店。"}},{"pos":"VERB 动词","cn":"停止;终止;放弃","en":"If you drop an idea, course of action, or habit, you do not continue with it.","ex":{"en":"He was told to drop the idea","cn":"他被告知要打消那个主意。"}},{"pos":"VERB 动词","cn":"(运动队或组织)把…除名","en":"If someone is dropped by a sports team or organization, they are no longer included in that team or employed by that organization.","ex":{"en":"The country's captain was dropped from the tour party to England.","cn":"该国的国家队队长无缘英格兰之行。"}},{"pos":"VERB 动词","cn":"输掉","en":"If you drop a game or part of a game in a sports competition, you lose it.","ex":{"en":"Oremans has yet to drop a set.","cn":"奥尔曼斯还一局未输。"}},{"pos":"VERB 动词","cn":"(在比赛中)排位退后","en":"If you drop to a lower position in a sports competition, you move to that position.","ex":{"en":"Britain has dropped from second to third place in the league.","cn":"英国在联赛中的排名从第二位降到了第三位。"}},{"pos":"N-COUNT 可数名词","cn":"滴;少量;微量;一点点","en":"A drop of a liquid is a very small amount of it shaped like a little ball. In informal English, you can also use drop when you are referring to a very small amount of something such as a drink.","ex":{"en":"...a drop of blue ink","cn":"一滴蓝墨水"}},{"pos":"N-PLURAL 复数名词","cn":"滴剂","en":"Drops are a kind of medicine which you put drop by drop into your ears, eyes, or nose.","ex":{"en":"...eye drops.","cn":"眼药水"}},{"pos":"N-COUNT 可数名词","cn":"(水果味或巧克力味的)糖豆，糖果粒","en":"Fruit or chocolate drops are small round sweets with a fruit or chocolate flavour."},{"pos":"N-COUNT 可数名词","cn":"落差;垂直距离;下降距离","en":"You use drop to talk about vertical distances. For example, a thirty-foot drop is a distance of thirty feet between the top of a cliff or wall and the bottom of it.","ex":{"en":"There was a sheer drop just outside my window","cn":"我的窗外就是垂直深渊。"}},{"pos":"PHRASE 短语","cn":"随口说出;给出暗示","en":"If you drop a hint, you give a hint or say something in a casual way.","ex":{"en":"If I drop a few hints he might give me a cutting.","cn":"如果我给点暗示，他没准会送我一段插枝。"}},{"pos":"PHRASE 短语","cn":"(常指因不喜欢而让别人)终止谈论，不要谈论，谈到此为止","en":"If you want someone to drop the subject ,drop it, or let it drop, you want them to stop talking about something, often because you are annoyed that they keep talking about it.","ex":{"en":"Mary Ann wished he would just drop it","cn":"玛丽·安希望他就不要谈论它了。"}},{"pos":"See also:","cn":"","en":"to drop dead→see: ; at the drop of a hat→see: ; to drop someone a line→see: ; a drop in the ocean→see: ;"},{"pos":"","cn":"","en":"相关词组：drop away drop by drop in drop off drop out"}]},"examples":[{"en":"You left your jacket, but I can drop it off on my way to work tomorrow.","cn":"你忘了拿你的短上衣，不过我可以在明天上班的路上顺便捎给你。"},{"en":"He spoke with a cockney accent and dropped his aitches (= did not pronounce the letter ‘h’ at the start of words).","cn":"他讲话带着伦敦东区的口音，把词首的 h 音给吞掉了。"}]},"dramatically":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a great and sudden way","cn":"大幅地；显著地；急剧地"},{"en":"in a way that is intended to be impressive, so that people notice","cn":"夸张做作地；戏剧性地"}]},"examples":[{"en":"Output has increased dramatically.","cn":"产量已大幅度提高。","src":"ld"},{"en":"Three years on, Jack’s life has dramatically changed .","cn":"三年之后，杰克的生活发生了巨大的变化。","src":"ld"}],"media":{"uk":"media/uk/dramatically__gb_1.mp3","us":"media/us/dramatically__us_1.mp3"},"oxford":{"phon":"drəˈmætɪkli","pos":"adverb","senses":[{"en":"very suddenly and to a very great and often surprising degree","cn":"突然；急剧地；令人吃惊地","ex":{"en":"Prices have fallen dramatically.","cn":"价格暴跌。"}},{"en":"in a way that is exciting and impressive","cn":"激动人心地；令人兴奋难忘地","ex":{"en":"The mountains rose dramatically behind them.","cn":"群山在他们身后兀然耸立。"}},{"en":"in a way that is connected with the theatre or plays","cn":"在戏剧（或戏剧艺术）方面","ex":{"en":"The opera does not compare musically or dramatically with the composer's best work.","cn":"这部歌剧在作曲和戏剧方面都无法跟作曲家最好的作品相提并论。"}},{"en":"in a way that is exaggerated in order to create a special effect and attract people's attention","cn":"戏剧性地；戏剧般地","ex":{"en":"‘At last!’ she cried dramatically.","cn":"“终于等到了！”她夸张地喊道。"}}]}},"drink":{"media":{"uk":"media/uk/drink__gb_1.mp3","us":"media/us/drink__us_1.mp3","img":["media/ldoce/img/drink.jpg"]},"oxford":{"phon":"drɪŋk","pos":"noun","senses":[{"en":"a liquid for drinking; an amount of a liquid that you drink","cn":"饮料；一杯，一份，一口（饮料）","g":"[countable, uncountable]","ex":{"en":"Can I have a drink?","cn":"给我来一杯饮料好吗？"}},{"en":"alcohol or an alcoholic drink; something that you drink on a social occasion","cn":"酒；酒精饮料","g":"[countable, uncountable]","lab":"British English","ex":{"en":"They went for a drink together.","cn":"他们一起去喝酒了。"}},{"en":"a social occasion where you have alcoholic drinks","cn":"酒宴；酒会","g":"[plural]","ex":{"en":"Would you like to come for drinks on Sunday?","cn":"星期天来参加酒宴好吗？"}},{"en":"to take liquid into your mouth and then down your throat into your stomach","cn":"喝；饮","g":"[transitive, intransitive]","ex":{"en":"I don't drink coffee.","cn":"我不喝咖啡。"},"pos":"verb"},{"en":"to drink alcohol, especially when it is done regularly","cn":"喝酒；（尤指）酗酒","g":"[intransitive, transitive]","ex":{"en":"He doesn't drink.","cn":"他不喝酒。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"喝;饮","en":"When you drink a liquid, you take it into your mouth and swallow it.","ex":{"en":"He drank his cup of tea","cn":"他喝他的那杯茶。"}},{"pos":"VERB 动词","cn":"喝酒","en":"To drink means to drink alcohol.","ex":{"en":"He was smoking and drinking too much","cn":"他嗜烟酗酒。"}},{"pos":"N-COUNT 可数名词","cn":"一杯,一口,一份(饮料)","en":"A drink is an amount of a liquid which you drink.","ex":{"en":"I'll get you a drink of water.","cn":"我给你来杯水。"}},{"pos":"N-COUNT 可数名词","cn":"酒;酒精饮料","en":"A drink is an alcoholic drink.","ex":{"en":"She felt like a drink after a hard day.","cn":"辛苦了一天后她想喝上一杯。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"酒(如啤酒、葡萄酒或威士忌)","en":"Drink is alcohol, such as beer, wine, or whisky.","ex":{"en":"Too much drink is bad for your health.","cn":"酗酒有害健康。"}},{"pos":"PHRASE 短语","cn":"醉得不省人事;烂醉如泥;酩酊大醉","en":"If you drink yourself into a stupor or drink yourself into oblivion, you drink so much alcohol that you lose consciousness or fall deeply asleep.","ex":{"en":"We drank ourselves into a stupor on cheap wine.","cn":"我们喝廉价葡萄酒喝得酩酊大醉。"}},{"pos":"PHRASE 短语","cn":"比…更能喝酒;酒量比…大;灌醉","en":"If someone drinks you under the table, they drink more alcohol than you are able to on a particular occasion.","ex":{"en":"At sixteen he could drink me under the table.","cn":"16 岁的时候他就能把我灌醉了。"}},{"pos":"PHRASE 短语","cn":"(因沮丧或忧虑)纵酒,酗酒","en":"If someone takes to drink, they start to drink a lot of alcohol regularly, usually because they are depressed or worried about something.","ex":{"en":"He took to drink after his wife died.","cn":"他妻子过世后他就沉溺于酒中了。"}},{"pos":"CONVENTION 惯用语","cn":"可以;行;同意","en":"People say 'I'll drink to that' to show that they agree with and approve of something that someone has just said."},{"pos":"","cn":"","en":"to drink someone's health→see: ;"},{"pos":"","cn":"","en":"相关词组：drink in drink to drink up"}]},"examples":[{"en":"She took to drink (= often drank too much alcohol) after her marriage broke up.","cn":"婚姻破裂后，她染上了酗酒的恶习。"},{"en":"She took a drink from the glass and then put it down.","cn":"她喝了一口饮料，然后放下杯子。"}]},"drill":{"media":{"img":["media/ldoce/img/drill.jpg","media/pic/tools_diy_comp.jpg"],"uk":"media/uk/drill__gb_1.mp3","us":"media/us/drill__us_1.mp3"},"oxford":{"phon":"drɪl","pos":"noun","senses":[{"en":"a tool or machine with a pointed end for making holes","cn":"钻；钻头；钻床；钻机","g":"[countable]","ex":{"en":"an electric drill","cn":"电钻"}},{"en":"a way of learning something by means of repeated exercises","cn":"练习；训练","g":"[countable, uncountable]"},{"en":"a practice of what to do in an emergency, for example if there is a fire","cn":"（应对紧急情况的）演习","g":"[countable, uncountable]","ex":{"en":"a fire drill","cn":"消防演习"}},{"en":"military training in marching, the use of weapons, etc.","cn":"军事训练；操练","g":"[uncountable]","ex":{"en":"rifle drill","cn":"步枪操练"}},{"en":"the correct or usual way to do something","cn":"正确的步骤；常规；程序","g":"[singular]","lab":"old-fashioned","ex":{"en":"What's the drill for claiming expenses?","cn":"报销费用的手续是什么？"}},{"en":"a type of strong cotton cloth","cn":"粗斜纹布","g":"[uncountable]"},{"en":"a machine for planting seeds in rows","cn":"条播机","g":"[countable]","ex":{"en":"a seed drill","cn":"播种机"}},{"en":"to make a hole in something, using a drill","cn":"钻（孔）；打（眼）","g":"[transitive, intransitive]","ex":{"en":"Drill a series of holes in the frame.","cn":"在构架上钻一串孔。"},"pos":"verb"},{"en":"to try to get oil or water by drilling in the ground or sea bed","cn":"钻井","g":"[intransitive]","ex":{"en":"They're drilling for oil off the Irish coast.","cn":"他们在爱尔兰沿海钻井采油。"},"pos":"verb"},{"en":"to teach somebody to do something by making them repeat it a lot of times","cn":"培训；训练","g":"[transitive]","ex":{"en":"The children were drilled to leave the classroom quickly when the fire bell rang.","cn":"孩子们接受了如何在火警铃拉响时迅速离开教室的训练。"},"pos":"verb"},{"en":"to train soldiers to perform military actions","cn":"进行军事训练；操练","g":"[transitive]","ex":{"en":"The soldiers were being drilled outside the barracks.","cn":"士兵们正在军营外进行操练。"},"pos":"verb"},{"en":"to hit or kick a ball hard and in a straight line","cn":"大力直射","g":"[transitive]","ex":{"en":"She drilled the ball into the back of the net.","cn":"她用力把球直直打入网窝。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钻头;钻床;电钻","en":"A drill is a tool or machine that you use for making holes.","ex":{"en":"...pneumatic drills.","cn":"风钻"}},{"pos":"VERB 动词","cn":"钻(孔);打(眼)","en":"When you drill into something or drill a hole in something, you make a hole in it using a drill.","ex":{"en":"He drilled into the wall of Lili's bedroom","cn":"他在莉莉卧室的墙上钻了个孔。"}},{"pos":"VERB 动词","cn":"钻探(石油或水源)","en":"When people drill for oil or water, they search for it by drilling deep holes in the ground or in the bottom of the sea.","ex":{"en":"There have been proposals to drill for more oil","cn":"有人提议钻探更多的石油。"}},{"pos":"N-COUNT 可数名词","cn":"（学生的）反复练习","en":"A drill is a way that teachers teach their students something by making them repeat it many times.","ex":{"en":"The teacher runs them through a drill — the days of the week, the weather and some counting.","cn":"老师带他们做了反复练习：一周中每一天的叫法、天气和数数。"}},{"pos":"VERB 动词","cn":"教…做练习;反复训练","en":"If you drill people, you teach them to do something by making them repeat it many times.","ex":{"en":"He drills the choir to a high standard.","cn":"他将合唱团训练到了一个高水平。"}},{"pos":"N-VAR 可变名词","cn":"(尤指士兵进行的)练习,训练,操练","en":"A drill is repeated training for a group of people, especially soldiers, so that they can do something quickly and efficiently.","ex":{"en":"The Marines carried out a drill that included 18 ships and 90 aircraft","cn":"海军陆战队进行了有 18 艘军舰和 90 架飞机参与的训练。"}},{"pos":"N-COUNT 可数名词","cn":"(为在危急情况下逃生而进行的)常规训练,演习","en":"A drill is a routine exercise or activity, in which people practise what they should do in dangerous situations.","ex":{"en":"...a fire drill.","cn":"消防演习"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粗斜纹布","en":"Drill is thick cotton material which is used for making uniforms and trousers.","ex":{"en":"...cotton drill.","cn":"厚斜纹棉布"}},{"pos":"N-COUNT 可数名词","cn":"条播沟","en":"A drill is a long line in the earth, a few centimetres deep, which a farmer or gardener makes to plant seeds in.","ex":{"en":"Sow the seeds in drills about 1/2in. deep and 12in. apart.","cn":"在深约 0.5 英寸,间隔 12 英寸的条播沟里播种。"}}]},"examples":[{"en":"The children were drilled to leave the classroom quickly when the fire bell rang.","cn":"孩子们接受了如何在火警钟拉响时迅速离开教室的训练。"},{"en":"Navigation is good and there's a display to show how far you've drilled down.","cn":"导航很好，可以显示你正在看哪一级信息。"}]},"dressing":{"media":{"uk":"media/uk/dressing__gb_1.mp3","us":"media/us/dressing__us_1.mp3"},"oxford":{"phon":"ˈdresɪŋ","pos":"noun","senses":[{"en":"a thin sauce added to salads, usually made from oil, vinegar, salt, pepper, etc.","cn":"色拉调味汁；色拉酱汁","g":"[countable, uncountable]","ex":{"en":"a low-calorie dressing","cn":"低热量调料"}},{"en":"a mixture of food such as bread, onions and herbs, cut into very small pieces and placed inside a chicken, etc. before it is cooked","cn":"（烹饪前塞入鸡等膛内的）填料","g":"[uncountable]","lab":"North American English"},{"en":"a piece of soft material placed over a wound in order to protect it","cn":"（保护伤口的）敷料","g":"[countable]","ex":{"en":"Place the dressing directly onto the wound and hold it in place.","cn":"把敷料直接放到伤口上，固定住。"}},{"en":"the act of putting on clothes","cn":"穿衣；穿戴","g":"[uncountable]","ex":{"en":"Many of our patients need help with dressing.","cn":"我们的许多病人需要有人帮助穿衣。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(用油、醋、香料等制成的,拌色拉用的)调料","en":"A salad dressing is a mixture of oil, vinegar, and herbs or flavourings, which you pour over salad.","ex":{"en":"Mix the ingredients for the dressing in a bowl.","cn":"在碗里将各种原料混成调料。"}},{"pos":"N-COUNT 可数名词","cn":"(保护伤口用的)敷料","en":"A dressing is a covering that is put on a wound to protect it while it heals.","ex":{"en":"Miss Finkelstein will put a dressing on your thumb.","cn":"芬克尔斯坦小姐会为你包扎拇指的。"}}]},"examples":[{"en":"Many of our patients need help with dressing.","cn":"我们的许多病人需要有人帮助穿衣。"},{"en":"The nurse came to change his dressing.","cn":"护士来给他换敷料。"}],"base":"dress"},"drone":{"media":{"uk":"media/uk/drone__gb_1.mp3","us":"media/us/drone__us_1.mp3"},"oxford":{"phon":"drəʊn","pos":"noun","senses":[{"en":"an aircraft without a pilot, controlled from the ground, used for taking photographs, dropping bombs, delivering goods, etc.","cn":"无人机","ex":{"en":"aerial/surveillance drones","cn":"空中／监视无人机"}},{"en":"a continuous low noise","cn":"嗡嗡声","g":"[usually singular]","ex":{"en":"the distant drone of traffic","cn":"远处车辆往来发出的嗡嗡声"}},{"en":"a continuous low sound made by some musical instruments, for example the bagpipes, over which other notes are played or sung; the part of the instrument that makes this noise","cn":"持续低音（如风笛等发出的持续音）；持续音音管（或弦等）","g":"[usually singular]"},{"en":"a male bee that does not work","cn":"雄蜂"},{"en":"a person who is lazy and gives nothing to society while others work","cn":"（不劳动，依赖他人为生的）寄生虫","ex":{"en":"The medieval lord of the manor was what some today would call a drone.","cn":"中世纪庄园的领主在今天有些人眼中就是一名懒汉。"}},{"en":"to make a continuous low noise","cn":"嗡嗡叫；嗡嗡响","ex":{"en":"A plane was droning in the distance.","cn":"飞机在远处嗡嗡地响。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"嗡嗡作响;嗡嗡叫","en":"If something drones, it makes a low, continuous, dull noise.","ex":{"en":"Above him an invisible plane droned through the night sky.","cn":"在他头顶上一架隐形飞机嗡嗡地飞过夜空。"}},{"pos":"VERB 动词","cn":"(人)絮絮叨叨地说,喋喋不休地说","en":"If you say that someone drones, you mean that they keep talking about something in a boring way.","ex":{"en":"Chambers' voice droned, maddening as an insect around his head","cn":"钱伯斯一直在他耳边嗡嗡地说个不停，他都快疯了。"}},{"pos":"N-COUNT 可数名词","cn":"游手好闲者;寄生虫","en":"People who do not contribute anything to society or to an organization are sometimes described as drones .","ex":{"en":"A few are dim-witted drones, but most are talented, frustrated, wasted people.","cn":"有几个是愚笨的寄生虫,但是大多数是有才能却不得志而自暴自弃的人。"}},{"pos":"N-COUNT 可数名词","cn":"雄蜂","en":"A drone is a male bee."},{"pos":"","cn":"","en":"相关词组：drone on"}]},"examples":[{"en":"A plane was droning in the distance.","cn":"飞机在远处嗡嗡地响。"},{"en":"the distant drone of traffic","cn":"远处车辆往来发出的嗡嗡声"}]},"drained":{"media":{"uk":"media/uk/drained__gb_1.mp3","us":"media/us/drained__us_1.mp3"},"oxford":{"phon":"dreɪnd","pos":"adjective","senses":[{"en":"very tired and without energy","cn":"精疲力竭；无精打采","ex":{"en":"She suddenly felt totally drained.","cn":"她突然感到精疲力竭。"}}]},"examples":[{"en":"The experience left her emotionally drained.","cn":"这次经历使得她在感情上心灰意懒。"},{"en":"She suddenly felt totally drained.","cn":"她突然感到精疲力竭。"}],"base":"drain"},"drama":{"media":{"uk":"media/uk/drama__gb_1.mp3","us":"media/us/drama__us_1.mp3"},"oxford":{"phon":"ˈdrɑːmə","pos":"noun","senses":[{"en":"a play for the theatre, television or radio","cn":"戏；剧","g":"[countable]","ex":{"en":"a costume/period/courtroom/crime drama","cn":"古装剧；历史剧；法庭剧；犯罪剧"}},{"en":"plays considered as a form of literature","cn":"戏剧文学；戏剧艺术；戏剧","g":"[uncountable]","ex":{"en":"classical/modern drama","cn":"古典／现代戏剧"}},{"en":"an exciting event","cn":"戏剧性事件；戏剧性情节","g":"[countable]","ex":{"en":"A powerful human drama was unfolding before our eyes.","cn":"一个极富人情味的戏剧性事件在我们的眼前上演了。"}},{"en":"the fact of being exciting","cn":"激动；兴奋；刺激","g":"[uncountable]","ex":{"en":"You couldn't help being thrilled by the drama of the situation.","cn":"这充满激情的场面令人不禁激动不已。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"戏;剧","en":"A drama is a serious play for the theatre, television, or radio.","ex":{"en":"He acted in radio dramas.","cn":"他在广播剧中扮演角色。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"戏剧;戏剧艺术;戏剧事业","en":"You use drama to refer to plays in general or to work that is connected with plays and the theatre, such as acting or producing.","ex":{"en":"He knew nothing of Greek drama","cn":"他对希腊戏剧一无所知。"}},{"pos":"N-VAR 可变名词","cn":"戏剧性事件;戏剧性情节","en":"You can refer to a real situation which is exciting or distressing as drama .","ex":{"en":"There was none of the drama and relief of a hostage release","cn":"丝毫没有释放人质时的那种激动和如释重负的感觉。"}}]},"examples":[{"en":"A powerful human drama was unfolding before our eyes.","cn":"一个极富人情味的戏剧性事件在我们的眼前上演了。"},{"en":"You couldn't help being thrilled by the drama of the situation.","cn":"这充满激情的场面令人不禁激动不已。"}]},"dreamy":{"media":{"uk":"media/uk/dreamy__gb_1.mp3","us":"media/us/dreamy__us_1.mp3"},"oxford":{"phon":"ˈdriːmi","pos":"adjective","senses":[{"en":"looking as though you are thinking about other things and not paying attention to what is happening around you","cn":"做白日梦的；心不在焉的","ex":{"en":"She had a dreamy look in her eyes.","cn":"她眼里带着心不在焉的神色。"}},{"en":"having a lot of imagination, but not very realistic","cn":"爱幻想的（不切实际）","ex":{"en":"Paul was dreamy and not very practical.","cn":"保罗喜欢幻想，不太讲究实际。"}},{"en":"as if you are asleep or in a dream","cn":"似在梦中的；模糊的；朦胧的；恍惚的","ex":{"en":"He moved in the dreamy way of a man in a state of shock.","cn":"他惊魂未定，恍恍惚惚。"}},{"en":"pleasant and gentle; that makes you feel relaxed","cn":"怡然的；恬静的；轻松的","lab":"informal","ex":{"en":"a slow, dreamy melody","cn":"缓慢柔和的旋律"}},{"en":"beautiful; wonderful","cn":"漂亮的；美妙的；极好的","lab":"informal","ex":{"en":"What's he like? I bet he's really dreamy.","cn":"他长得如何？我敢说他一定很俊。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恍惚的;出神的","en":"If you say that someone has a dreamy expression, you mean that they are not paying attention to things around them and look as if they are thinking about something pleasant.","ex":{"en":"His face assumed a sort of dreamy expression.","cn":"他脸上现出一种恍惚的表情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻柔的;柔和的;梦幻（般）的","en":"If you describe something as dreamy, you mean that you like it and that it seems gentle and soft, like something in a dream.","ex":{"en":"...dreamy shots of beautiful sunsets.","cn":"梦幻般的美丽晚霞的照片"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不切实际的;爱空想的","en":"If you describe a person or an idea as dreamy, you mean that they are not very practical.","ex":{"en":"He's like some dreamy kid playing on his own","cn":"他就像是个自娱自乐的爱幻想的孩子。"}}]},"examples":[{"en":"What's he like? I bet he's really dreamy.","cn":"他长得如何？我敢说他一定很俊。"},{"en":"Paul was dreamy and not very practical.","cn":"保罗喜欢幻想，不太讲究实际。"}]},"drawers":{"oxford":{"phon":"drɔːz","pos":"noun","senses":[{"en":"knickers or underpants, especially ones that cover the upper parts of the legs","cn":"（长）内裤"}]},"media":{"uk":"media/uk/drawers__gb_1.mp3","us":"media/us/drawers__us_1.mp3"},"base":"drawer"},"drab":{"oxford":{"phon":"dræb","pos":"adjective","senses":[{"en":"without interest or colour; boring","cn":"单调乏味的；无光彩的；无生气的","ex":{"en":"She longed to be out of the cold, drab little office.","cn":"她渴望离开那个冷冰冰的小办公室。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单调乏味的;缺乏生气的","en":"If you describe something as drab, you think that it is dull and boring to look at or experience.","ex":{"en":"Mary was wearing the same drab grey dress.","cn":"玛丽穿着同一件毫无朝气的灰色裙子。"}}]},"media":{"uk":"media/uk/drab__gb_1.mp3","us":"media/us/drab__us_1.mp3"},"examples":[{"en":"drab women, dressed in browns and greys","cn":"身着棕灰二色衣服毫无光彩的女人"},{"en":"a cold drab little office","cn":"冷冰冰的小办公室"}]},"drawer":{"media":{"uk":"media/uk/drawer__gb_1.mp3","us":"media/us/drawer__us_1.mp3","img":["media/ldoce/img/chest_drawers.jpg"]},"oxford":{"phon":"","pos":"noun","senses":[{"en":"a part of a piece of furniture such as a desk, used for keeping things in. It is like a box in shape and has a handle on the front for pulling it out.","cn":"抽屉","ex":{"en":"in the top/middle/bottom drawer of the desk","cn":"写字台的上层／中层／下层抽屉"}},{"en":"a person who produces a drawing or design","cn":"制图员","ex":{"en":"He is an expert drawer and painter.","cn":"他是一位专业的抽屉和画家。"}},{"en":"a person who writes a cheque (= a printed form that you can write on and sign as a way of paying for something instead of using money)","cn":"开票人；出票人","lab":"formal","ex":{"en":"a cheque bearing the signature of the drawer","cn":"带有出票人签名的支票"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"抽屉","en":"A drawer is part of a desk, chest, or other piece of furniture that is shaped like a box and is designed for putting things in. You pull it towards you to open it.","ex":{"en":"He opened a drawer in his writing-table.","cn":"他打开了写字台的一个抽屉。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指女式)内裤","en":"Drawers are underpants, especially ones worn by women."}]},"examples":[{"en":"in the top/middle/bottom drawer of the desk","cn":"写字台的上层/中层/下层抽屉"},{"en":"She took a file from her desk drawer .","cn":"她从书桌的抽屉里拿出了一个文件夹。"}]},"dramatic":{"media":{"uk":"media/uk/dramatic__gb_1.mp3","us":"media/us/dramatic__us_1.mp3"},"oxford":{"phon":"drəˈmætɪk","pos":"adjective","senses":[{"en":"sudden, very great and often surprising","cn":"突然的；巨大的；令人吃惊的","ex":{"en":"a dramatic increase/change/improvement/shift","cn":"暴涨；巨变；大幅改进；剧变"}},{"en":"exciting and impressive","cn":"激动人心的；令人兴奋难忘的","ex":{"en":"a dramatic victory","cn":"激动人心的胜利"}},{"en":"connected with the theatre or plays","cn":"戏剧的；有关戏剧的；戏剧艺术的","g":"[usually before noun]","ex":{"en":"a local dramatic society","cn":"地方戏剧协会"}},{"en":"exaggerated in order to create a special effect and attract people’s attention","cn":"戏剧性的；戏剧般的；夸张做作的","ex":{"en":"He flung out his arms in a dramatic gesture.","cn":"他夸张地张开双臂。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"突如其来的;急剧的;引人注目的","en":"A dramatic change or event happens suddenly and is very noticeable and surprising.","ex":{"en":"A fifth year of drought is expected to have dramatic effects on the California economy","cn":"第五年遭受旱灾预计会对加利福尼亚的经济产生巨大的影响。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"激动人心的;引人注目的;令人印象深刻的","en":"A dramatic action, event, or situation is exciting and impressive.","ex":{"en":"He witnessed many dramatic escapes as people jumped from as high as the fourth floor","cn":"他目睹了许多人从五层高的楼上跳下来逃生的惊险场面。"}},{"pos":"ADJ 形容词","cn":"戏剧的;有关戏剧的;戏剧学的","en":"You use dramatic to describe things connected with or relating to the theatre, drama, or plays.","ex":{"en":"...a dramatic arts major in college","cn":"大学里戏剧艺术专业的学生"}}]},"examples":[{"en":"They watched dramatic pictures of the police raid on TV.","cn":"他们在电视上看到了警察突击搜捕的激动人心的画面。"},{"en":"The announcement had a dramatic effect on house prices.","cn":"这项公告对房屋价格产生了巨大的影响。"}]},"dramas":{"lemma":"drama"},"drivers":{"lemma":"driver"},"dropping":{"lemma":"drop"},"drowned":{"oxford":{"phon":"draʊn","pos":"verb","senses":[{"en":"to die because you have been underwater too long and you cannot breathe; to kill sb in this way （","cn":"使）淹死，溺死"},{"en":"to make sth very wet; to completely cover sth in water or another liquid","cn":"浸透；淹没；浸泡"}]}},"druggists":{"oxford":{"phon":"ˈdrʌɡɪst","pos":"noun","senses":[{"en":"a person whose job is to prepare and sell medicines, and who works in a shop","cn":"药剂师；药商"}]}},"dropped":{"lemma":"drop"},"dragged":{"oxford":{"phon":"dræɡ","pos":"verb","senses":[{"en":"to pull sb/sth along with effort and difficulty （","cn":"使劲而吃力地）拖，拉，拽，扯"},{"en":"to move yourself slowly and with effort","cn":"缓慢而费力地移动（或行进）"}]}},"dreams":{"lemma":"dream"},"drills":{"lemma":"drill"},"dreamed":{"lemma":"dream"},"dresses":{"lemma":"dress"},"drums":{"lemma":"drum"},"drawings":{"lemma":"draw"},"drinks":{"lemma":"drink"},"drugstores":{"lemma":"drugstore"},"drawbacks":{"lemma":"drawback"},"drapes":{"lemma":"drape","media":{"uk":"media/ldoce/hwd/bre/d/ld41drapes.mp3","us":"media/ldoce/hwd/ame/d/drapes.mp3"}},"dragging":{"oxford":{"phon":"dræɡ","pos":"verb","senses":[{"en":"to pull sb/sth along with effort and difficulty （","cn":"使劲而吃力地）拖，拉，拽，扯"},{"en":"to move yourself slowly and with effort","cn":"缓慢而费力地移动（或行进）"}]}},"dr":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"(in writing) Doctor","cn":"（书写形式）医生，博士","ex":{"en":"Dr (Jane) Walker","cn":"（简·）沃克博士"}},{"en":"(in street names) drive","cn":"（用于街道名）路，大道"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Dr is a written abbreviation for (书面缩略=) Doctor .","ex":{"en":"...Dr John Hardy of St Mary's Medical School in London.","cn":"伦敦圣玛丽医学院的约翰·哈代博士"}},{"pos":"","cn":"(用于街道名)路，大道","en":"Dr is used as a written abbreviation for (书面缩略=) Drive when it is part of a street name.","ex":{"en":"...6 Queen's Dr.","cn":"女王大道 6 号"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/lpd_dr.mp3","us":"media/ldoce/hwd/ame/d/lpd_dr.mp3"},"examples":[{"en":"Dr (Jane) Walker （","cn":"简）沃克博士"},{"en":"88 Park Dr","cn":"公园大道88号"}]},"dressmakers":{"oxford":{"phon":"ˈdresmeɪkə(r)","pos":"noun","senses":[{"en":"a person who makes women's clothes, especially as a job （","cn":"女装）裁缝"}]}},"dreaming":{"lemma":"dream"},"draws":{"lemma":"draw"},"drives":{"lemma":"drive"},"drizzle":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毛毛雨;蒙蒙细雨","en":"Drizzle is light rain falling in fine drops.","ex":{"en":"The drizzle had now stopped and the sun was breaking through.","cn":"毛毛雨现在已经停了,太阳正破云而出。"}},{"pos":"VERB 动词","cn":"下毛毛雨;下蒙蒙细雨","en":"If it is drizzling, it is raining very lightly.","ex":{"en":"Clouds had come down and it was starting to drizzle","cn":"云层压低,开始飘起了毛毛雨。"}},{"pos":"VERB 动词","cn":"(在食物上)滴，淋，洒","en":"If you drizzle a liquid over food or drizzle food with a liquid, you pour a small quantity of the liquid all over the food.","ex":{"en":"Drizzle the remaining dressing over the duck and salad","cn":"将剩下的调料淋在鸭肉和色拉上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a liquid or other substance flow out of or into a container by holding it at an angle","cn":""},{"en":"to pour a liquid onto food in small drops or in a small stream – often used in cooking instructions","cn":""},{"en":"to pour something out of a container by turning it upside down","cn":""}]},"collocations":{"phrases":["ADJ. fine, light, thin | steady | patchy","DRIZZLE + VERB fall Light drizzle fell all afternoon.","PREP. in/through a/the ~ We walked home through the drizzle."]},"media":{"uk":"media/ldoce/hwd/bre/1/drizzle_v0205.mp3","us":"media/ldoce/hwd/ame/7/drizzle1.mp3"},"examples":[{"en":"a dull, drizzly morning","cn":"阴雨蒙蒙的早上"},{"en":"The rain isn’t too bad – it’s only drizzling.","cn":"雨下得不大——只是毛毛细雨而已。"}],"oxford":{"phon":"ˈdrɪzl","pos":"verb","senses":[{"en":"when it is drizzling, it is raining lightly","cn":"下毛毛雨；下蒙蒙细雨","g":"[intransitive]","ex":{"en":"It was drizzling outside.","cn":"外面下着毛毛细雨。"}},{"en":"to pour a small amount of liquid over the surface of something","cn":"（毛毛雨似的）洒落","g":"[transitive]","ex":{"en":"Drizzle the lemon juice over the fish.","cn":"在鱼上淋上柠檬汁。"}},{"en":"light fine rain","cn":"毛毛细雨","ex":{"en":"The forecast for tomorrow is mist and drizzle.","cn":"天气预报说明天有薄雾和小雨。"},"pos":"noun"}]}},"drawl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拉长调子说;慢吞吞地说","en":"If someone drawls, they speak slowly and not very clearly, with long vowel sounds.","ex":{"en":"'I guess you guys don't mind if I smoke?' he drawled","cn":"“伙计们，我想你们不介意我抽烟吧？”他拉长音调说。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to speak slowly, with vowel sounds that are longer than usual 〔","cn":"拉长元音〕慢吞吞地说"}]},"collocations":{"phrases":["ADV. lazily, sardonically, slowly, softly &lsquo;Come in,&rsquo; he drawled softly."]},"media":{"uk":"media/ldoce/hwd/bre/0/drawl0205.mp3","us":"media/ldoce/hwd/ame/d/drawl.mp3"},"examples":[{"en":"‘Hi there!’ she drawled lazily. “","cn":"喂，你好！”她拖着长腔懒洋洋地说。"},{"en":"She spoke in a slow southern drawl.","cn":"她带着南方的拖腔慢条斯理地讲话。"}],"oxford":{"phon":"drɔːl","pos":"noun","senses":[{"en":"a way of speaking slowly with vowel sounds that are longer than usual","cn":"（拉长调子）慢吞吞地说","ex":{"en":"She spoke in a slow southern drawl.","cn":"她说话慢条斯理，还带着南方人的拖腔。"}},{"en":"to speak or say something slowly with vowel sounds that are longer than usual","cn":"（拉长调子）慢吞吞地说","ex":{"en":"‘Hi there!’ she drawled lazily.","cn":"“喂，你好！”她拖着长腔懒洋洋地说。"},"pos":"verb"}]}},"draught":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"穿堂风;通风气流","en":"A draught is a current of air that comes into a place in an undesirable way.","ex":{"en":"Block draughts around doors and windows","cn":"挡住门窗处的穿堂风。"}},{"pos":"ADJ 形容词","cn":"桶装的;散装的","en":"Draught beer is beer which is kept in barrels rather than bottles.","ex":{"en":"Draught beer is available too.","cn":"还提供桶装啤酒。"}},{"pos":"N-COUNT 可数名词","cn":"一大口","en":"A draught of liquid is a large amount that you swallow.","ex":{"en":"He took a draught of beer","cn":"他喝了一大口啤酒。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"国际跳棋;西洋跳棋","en":"Draughts is a game for two people, played with 24 round pieces on a board.","ex":{"en":"He was in the study playing draughts by the fire with Albert.","cn":"他正和艾伯特在书房的炉火旁下国际跳棋。"}},{"pos":"N-COUNT 可数名词","cn":"(国际跳棋的)棋子","en":"A draught is one of the round pieces which are used in the game of draughts."},{"pos":"ADJ 形容词","cn":"（牲畜）役用的，拉车的","en":"A draught animal is one which pulls heavy loads, for example on a farm.","ex":{"en":"...an Irish draught mare.","cn":"爱尔兰役用母马"}},{"pos":"N-COUNT 可数名词","cn":"药水;饮剂","en":"A draught is a medicine in the form of a liquid which you drink.","ex":{"en":"One of the night-duty nuns gave her a sleeping draught.","cn":"一个值夜班的修女给了她一剂安眠药水。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"air moving in a current, especially strongly or quickly","cn":""},{"en":"a gentle pleasant wind","cn":""},{"en":"a current of cool air which blows into a room, especially one that makes you feel uncomfortable","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n 4 n 5 v","senses":[{"en":"If you're chilly, you might close a window that's letting in a draught . Draught is the British spelling of the word draft ."}]},"collocations":{"phrases":["ADJ. cold, icy A cold draught of air blew in from the open window.","VERB + DRAUGHT create | prevent","DRAUGHT + VERB blow, come, whistle a draught coming under the door","DRAUGHT + NOUN excluder, proofing Fit draught excluders to the bottoms of doors.","PREP. ~ from the draught from the window","PHRASES a draught of air"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdedraught.mp3","us":"media/ldoce/hwd/ame/1/draft1.mp3"},"examples":[{"en":"A cold draught of air blew in from the open window.","cn":"一股寒气从敞开的窗户吹了进来。"},{"en":"He took a deep draught of his beer.","cn":"他喝了一大口啤酒。"}],"oxford":{"phon":"drɑːft","pos":"noun","senses":[{"en":"a flow of cool air in a room or other small space","cn":"穿堂风；通风气流；通风","g":"[countable]","ex":{"en":"There's a draught in here.","cn":"这儿有一股冷风。"}},{"en":"one continuous action of swallowing liquid (= making it go down your throat); the amount swallowed","cn":"一饮（的量）","g":"[countable]","lab":"formal","ex":{"en":"He took a deep draught of his beer.","cn":"他喝了一大口啤酒。"}},{"en":"medicine in a liquid form","cn":"药水；饮剂","g":"[countable]","lab":"old use or literary","ex":{"en":"a sleeping draught (= one that makes you sleep)","cn":"一服安眠饮剂"}},{"en":"a game for two players using 24 round pieces on a board marked with black and white squares","cn":"国际跳棋；西洋跳棋","g":"[uncountable]","lab":"British English"},{"en":"one of the round pieces used in a game of draughts","cn":"国际跳棋棋子；西洋跳棋棋子","g":"[countable]","lab":"British English"},{"en":"served from a large container (= a barrel) rather than in a bottle","cn":"零售的；散装的","g":"[usually before noun]","ex":{"en":"draught beer","cn":"散装啤酒"},"pos":"adjective"},{"en":"used for pulling heavy loads","cn":"拖曳重载用的","g":"[only before noun]","ex":{"en":"a draught horse","cn":"役马"},"pos":"adjective"},{"en":"to write the first rough version of something such as a letter, speech, book or law","cn":"起草；草拟","ex":{"en":"I'll draught a letter for you.","cn":"我会为你起草一封信。"},"pos":"verb"},{"en":"to choose people and send them somewhere for a special task","cn":"选派；抽调","ex":{"en":"Extra police are being draughted in to control the crowds.","cn":"正在增派警察来控制人群。"},"pos":"verb"}]}},"drip":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)滴下","en":"When liquid drips somewhere, or you drip it somewhere, it falls in individual small drops.","ex":{"en":"Sit your child forward and let the blood drip into a tissue or on to the floor","cn":"让你的孩子前倾坐着，让血滴在纸巾上或地板上。"}},{"pos":"VERB 动词","cn":"(液体)滴出，滴下","en":"When something drips, drops of liquid fall from it.","ex":{"en":"A tap in the kitchen was dripping","cn":"厨房的水龙头在滴水。"}},{"pos":"N-COUNT 可数名词","cn":"水滴;滴液","en":"A drip is a small individual drop of a liquid.","ex":{"en":"Drips of water rolled down the trousers of his uniform.","cn":"他的制服裤子在不停地滴水。"}},{"pos":"N-COUNT 可数名词","cn":"(医用)滴注器","en":"A drip is a piece of medical equipment by which a liquid is slowly passed through a tube into a patient's blood.","ex":{"en":"I had a bad attack of pneumonia and spent two days in hospital on a drip.","cn":"我得了严重的肺炎，在医院输了两天液。"}},{"pos":"VERB 动词","cn":"含有;充满;充溢","en":"If you say that something is dripping with a particular thing, you mean that it contains a lot of that thing.","ex":{"en":"They were dazed by window displays dripping with diamonds and furs","cn":"他们被满橱窗陈列的钻石和皮草弄得眼花缭乱。"}},{"pos":"N-COUNT 可数名词","cn":"笨蛋;懦夫;平庸乏味者","en":"If you call someone a drip, you mean that they are rather stupid and lacking in enthusiasm or energy."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if liquid flows, it moves in a steady continuous stream","cn":""},{"en":"to flow – used when saying that something flows in a particular direction","cn":""},{"en":"to flow out of something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When water flows slowly in tiny drops, it drips . The movement of water in this way is called a drip ."}]},"collocations":{"phrases":["ADJ. slow, steady","PREP. ~ of the steady drip of water from the tap 2 drop of water that falls down from sb/sth","VERB + DRIP catch There were buckets to catch the drips from the ceiling.","DRIP + VERB fall Drips fell from the roof of the cave.","PREP. ~ from drips from the tap 3 medical equipment","ADJ. intravenous | saline","VERB + DRIP fix up, set up | be attached to, be on He is on a saline drip. | attach sb to, put sb on | take sb off He was taken off his drip"]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdedrip.mp3","us":"media/ldoce/hwd/ame/9/drip1.mp3"},"examples":[{"en":"The silence was broken only by the steady drip, drip of water from the roof.","cn":"只有屋顶上滴答滴答持续不断的滴水声打破了寂静。"},{"en":"We put a bucket under the hole in the roof to catch the drips.","cn":"我们在屋顶漏洞下放了一个水桶接水滴。"}],"oxford":{"phon":"drɪp","pos":"verb","senses":[{"en":"to fall in small drops","cn":"滴下","g":"[intransitive]","ex":{"en":"She was hot and sweat dripped into her eyes.","cn":"她很热，汗水滴入双眼。"}},{"en":"to produce or let fall drops of liquid","cn":"滴出；滴水","g":"[intransitive, transitive]","ex":{"en":"The tap was dripping.","cn":"龙头在滴水。"}},{"en":"to contain or hold a lot of something","cn":"含有；充满；充溢","g":"[intransitive, transitive]","ex":{"en":"The trees were dripping with fruit.","cn":"树上挂满了果子。"}},{"en":"the sound or action of small drops of liquid falling continuously","cn":"滴落；滴水声；滴答声","g":"[singular]","ex":{"en":"The silence was broken only by the steady drip, drip of water from the roof.","cn":"只有屋顶上滴答滴答持续不断的滴水声打破了寂静。"},"pos":"noun"},{"en":"a small drop of liquid that falls from something","cn":"水滴；滴液","g":"[countable]","ex":{"en":"We put a bucket under the hole in the roof to catch the drips.","cn":"我们在屋顶漏洞下放了一个水桶接水滴。"},"pos":"noun"},{"en":"a continuous, steady series of repeated events, usually bad events","cn":"一系列连续、稳定的重复事件，通常是坏事件","g":"[singular]","ex":{"en":"He may face a steady drip of new allegations as prosecutors question his associates.","cn":"随着检察官询问他的同伙，他可能会面临源源不断的新指控。"},"pos":"noun"},{"en":"a piece of equipment that passes liquid food, medicine or blood very slowly through a tube into a patient’s vein","cn":"（静脉）滴注","g":"[countable]","lab":"especially in North American English","ex":{"en":"She's been put on a drip.","cn":"她一直在输液。"},"pos":"noun"},{"en":"a boring or stupid person with a weak personality","cn":"怯懦讨厌的人；愚蠢胆怯的人","g":"[countable]","lab":"old-fashioned, informal，，","ex":{"en":"Don't be such a drip—come and join in the fun!","cn":"别犯傻了，过来一起玩吧！"},"pos":"noun"}]}},"drinker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"常饮…者;常喝…者","en":"If someone is a tea drinker or a beer drinker, for example, they regularly drink tea or beer.","ex":{"en":"Are you a coffee drinker?","cn":"你常喝咖啡吗？"}},{"pos":"N-COUNT 可数名词","cn":"饮酒者;(尤指)酗酒者，酒徒","en":"If you describe someone as a drinker, you mean that they drink alcohol, especially in large quantities.","ex":{"en":"You don't need to be a smoker or a drinker to risk heart disease","cn":"并不是只有抽烟喝酒的人才会犯心脏病。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who drinks too much alcohol and cannot stop","cn":""},{"en":"someone who is drunk or who often gets drunk - use this especially about someone you see in a public place such as a street or a bar","cn":""},{"en":"someone who often drinks a lot of alcohol","cn":""}]},"collocations":{"phrases":["ADJ. habitual, hard, heavy This liver condition is common in heavy drinkers. | moderate | problem help for the families and friends of probl"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdedrinker.mp3","us":"media/ldoce/hwd/ame/5/drinker.mp3"},"examples":[{"en":"a heavy/moderate drinker","cn":"酒鬼；有节制的饮酒者"},{"en":"a coffee drinker","cn":"常喝咖啡的人"}],"oxford":{"phon":"ˈdrɪŋkə(r)","pos":"noun","senses":[{"en":"a person who drinks alcohol regularly, especially somebody who drinks too much","cn":"饮酒者；（尤指）酗酒者，酒徒","ex":{"en":"a heavy/moderate drinker","cn":"酒鬼；有节制的饮酒者"}},{"en":"a person who regularly drinks the particular drink mentioned","cn":"常饮…酒者；常喝…饮料者","ex":{"en":"a coffee drinker","cn":"常喝咖啡的人"}}]}},"drought":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"久旱;旱灾","en":"A drought is a long period of time during which no rain falls.","ex":{"en":"Drought and famines have killed up to two million people here.","cn":"旱灾和饥荒夺去了这里200万人的生命。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden shaking of the Earth’s surface that often causes a lot of damage","cn":""},{"en":"a very large amount of water that covers an area that is usually dry","cn":""},{"en":"a long period of dry weather when there is not enough water for plants and animals to live","cn":"旱灾﹐干旱"}]},"vocab":{"pos":"n","senses":[{"en":"When there is a drought somewhere, there's not enough rainfall. In certain areas, a drought can last for weeks, months, sometimes even years! Forget about running your lawn sprinkler during a drought; the water is more needed for human hydration and toilet flushing."}]},"collocations":{"phrases":["ADJ. severe, terrible, worst It has been the worst drought in the country's history. | long, prolonged | summer","VERB + DROUGHT have England has had several summer droughts in recent years. | cause | break A week of good rains has broken the drought.","DROUGHT + VERB affect sth Large areas of Africa are affected by severe drought.","DROUGHT + NOUN conditions","PREP. during/in ~ Some of the newer plants in the garden died during the drought.","PHRASES in times of drought, months/years of drought"]},"media":{"uk":"media/ldoce/hwd/bre/6/drought0205.mp3","us":"media/ldoce/hwd/ame/4/drought.mp3"},"examples":[{"en":"one of the worst droughts on record","cn":"有记载以来最严重的旱灾之一"},{"en":"two years of severe drought","cn":"两年的严重旱灾"}],"oxford":{"phon":"draʊt","pos":"noun","senses":[{"en":"a long period of time when there is little or no rain","cn":"久旱；旱灾","ex":{"en":"Farmers are facing ruin after two years of severe drought.","cn":"两年来的严重干旱让农场主面临倾家荡产的境地。"}},{"en":"a long period of time when there is a lack of something that is needed or wanted","cn":"长期缺乏","ex":{"en":"The team is desperate to end a ten-game goal drought.","cn":"球队迫切希望结束十场比赛的进球荒。"}}]}},"drain":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"排出;(使)流出","en":"If you drain a liquid from a place or object, you remove the liquid by causing it to flow somewhere else. If a liquid drains somewhere, it flows there.","ex":{"en":"Miners built the tunnel to drain water out of the mines","cn":"矿工们开凿了一条地道，以排出矿井里的水。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)流干;(使)排干","en":"If you drain a place or object, you dry it by causing water to flow out of it. If a place or object drains, water flows out of it until it is dry.","ex":{"en":"Vast numbers of people have been mobilised to drain flooded land","cn":"大量的人力被动员去排干受涝的土地。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（水分）滤去，滤干","en":"If you drain food or if food drains, you remove the liquid that it has been in, especially after it has been cooked or soaked in water.","ex":{"en":"Drain the pasta well, arrange on four plates and pour over the sauce","cn":"将意大利面中的水分滤干，放在4个盘子里再淋上调味汁。"}},{"pos":"N-COUNT 可数名词","cn":"下水道;排水管;阴沟","en":"A drain is a pipe that carries water or sewage away from a place, or an opening in a surface that leads to the pipe.","ex":{"en":"Tony built his own house and laid his own drains.","cn":"托尼自己盖了房子并铺设了下水管道。"}},{"pos":"VERB 动词","cn":"喝干;喝光","en":"If someone drains a glass, they empty it by drinking what is in it.","ex":{"en":"Pamela drained her glass and refilled it.","cn":"帕梅拉喝完后又续了一杯。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）(脸上血色)消失，消退","en":"If the colour or the blood drains or is drained from someone's face, they become very pale. You can also say that someone's face drains or is drained of colour.","ex":{"en":"Harry felt the colour drain from his face","cn":"哈里觉得他脸上的血色在消失。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（情感）消失，消散","en":"If a feeling drains or is drained out of you, it gradually becomes less strong until you no longer feel it.","ex":{"en":"And then, suddenly, the euphoria began to drain away","cn":"随后，狂喜的感觉突然开始消失了。"}},{"pos":"VERB 动词","cn":"使精疲力竭;使心力交瘁","en":"If something drains you, it leaves you feeling physically and emotionally exhausted.","ex":{"en":"My emotional turmoil had drained me.","cn":"纷乱的情绪让我心力交瘁。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(精力)耗尽","en":"If energy drains or is drained from you, you lose all energy and become very tired.","ex":{"en":"As his energy drained away, his despair and worry grew","cn":"当他的精力耗尽时，他的绝望和担心也增加了。"}},{"pos":"N-SING 单数名词","cn":"(金钱或资源的)大量消耗，耗竭，耗费","en":"If you say that something is a drain on an organization's finances or resources, you mean that it costs the organization a large amount of money, and you do not consider that it is worth it.","ex":{"en":"...an ultra-modern printing plant, which has been a big drain on resources","cn":"资源消耗很大的超现代印刷厂"}},{"pos":"VERB 动词","cn":"用尽;耗尽;用完","en":"If you say that a country's or a company's resources or finances are drained, you mean that they are used or spent completely.","ex":{"en":"The state's finances have been drained by war","cn":"国家财力已经被战争消耗殆尽。"}},{"pos":"PHRASE 短语","cn":"被毁掉;被浪费掉","en":"If you say that something is going down the drain, you mean that it is being destroyed or wasted.","ex":{"en":"They were aware that their public image was rapidly going down the drain","cn":"他们意识到他们的公众形象正迅速被毁掉。"}},{"pos":"PHRASE 短语","cn":"破产;倒闭","en":"If you say that a business is going down the drain, you mean that it is failing financially.","ex":{"en":"Small local stores are going down the drain.","cn":"当地的小店都倒闭了。"}},{"pos":"","cn":"","en":"相关词组：drain off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to quickly drink large quantities of an alcoholic drink","cn":""},{"en":"to drink all of a drink fairly quickly, especially an alcoholic drink","cn":""},{"en":"to drink everything that is in a bottle etc, including the last few drops","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Most commonly found at the bottom of sinks and bathtubs across the globe, a drain is the hole through which water is carried away."}]},"collocations":{"phrases":["ADV. thoroughly, well Remove the artichokes, drain thoroughly and allow to cool. well-drained soil 2 make sb/sth weaker/poorer, etc.","ADV. totally, utterly | emotionally, physically | away draining away the country's coal reserves","PREP. of His voice was utterly drained of emotion.","PHRASES be/feel drained Sue felt exhausted and emotionally drained."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdedrain.mp3","us":"media/ldoce/hwd/ame/5/drain1.mp3"},"examples":[{"en":"You will need to drain the central heating system before you replace the radiator.","cn":"你得先把中央供暖系统的水排净再更换散热器。"},{"en":"My mother's hospital expenses were slowly draining my income.","cn":"我母亲的住院开销把我的收入渐渐耗光了。"}],"oxford":{"phon":"dreɪn","pos":"verb","senses":[{"en":"to make something empty or dry by removing the liquid from it; to become empty or dry in this way","cn":"排空；（使）流光；放干","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"Drain and rinse the pasta.","cn":"把通心粉过一过水。"}},{"en":"to make liquid flow away from something; to flow away","cn":"（使）流走，流出","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"We had to drain the oil out of the engine.","cn":"我们必须把发动机里的机油全部放掉。"}},{"en":"to empty a cup or glass by drinking everything in it","cn":"喝光；喝干","g":"[transitive]","ex":{"en":"In one gulp, he drained the glass.","cn":"他一口喝干了杯中的水。"}},{"en":"to make somebody/something weaker, poorer, etc. by using up their/its strength, money, etc.","cn":"使（精力、金钱等）耗尽","g":"[transitive]","ex":{"en":"My mother's hospital expenses were slowly draining my income.","cn":"我母亲的住院开销把我的收入渐渐耗光了。"}},{"en":"a pipe that carries away dirty water or other liquid waste","cn":"下水道；排水管","g":"[countable]","ex":{"en":"We had to call in a plumber to unblock the drain.","cn":"我们只得叫个管子工来疏通下水道。"},"pos":"noun"},{"en":"a frame of metal bars over the opening to a drain in the ground","cn":"下水道孔盖","g":"[countable]","lab":"British English","pos":"noun"},{"en":"a hole in a bath, sink, etc. where the water flows away and into which a plug fits","cn":"（浴缸、水池等的）排水孔，渗水孔，漏眼","g":"[countable]","lab":"US English","pos":"noun"},{"en":"a thing that uses a lot of the time, money, etc. that could be used for something else","cn":"消耗；耗竭；耗费","g":"[singular]","ex":{"en":"Military spending is a huge drain on the country's resources.","cn":"军费开支是对国家资源的巨大耗费。"},"pos":"noun"},{"en":"the fact of resources, people, etc. being lost or wasted","cn":"流失；浪费","g":"[uncountable]","ex":{"en":"the drain of talented staff to the United States","cn":"人才流失到美国"},"pos":"noun"}]}},"drift":{"collins":{"senses":[{"pos":"VERB 动词","cn":"飘移;漂流","en":"When something drifts somewhere, it is carried there by the movement of wind or water.","ex":{"en":"We proceeded to drift on up the river","cn":"我们继续向河流的上游漂流。"}},{"pos":"VERB 动词","cn":"无意间进入;不知不觉陷入","en":"If someone or something drifts into a situation, they get into that situation in a way that is not planned or controlled.","ex":{"en":"We need to offer young people drifting into crime an alternative set of values","cn":"我们需要给那些无意间犯了罪的年轻人灌输另一套价值观。"}},{"pos":"VERB 动词","cn":"流浪;漂泊","en":"If you say that someone drifts around, you mean that they travel from place to place without a plan or settled way of life.","ex":{"en":"You've been drifting from job to job without any real commitment.","cn":"你一直在无目的地更换工作，从未真正投入进去。"}},{"pos":"N-COUNT 可数名词","cn":"移动;动向;趋势;逐渐变化","en":"A drift is a movement away from somewhere or something, or a movement towards somewhere or something different.","ex":{"en":"...the drift towards the cities.","cn":"涌向城市的趋势"}},{"pos":"VERB 动词","cn":"缓慢移动;逐渐移动","en":"To drift somewhere means to move there slowly or gradually.","ex":{"en":"As rural factories shed labour, people drift towards the cities.","cn":"由于农村的工厂纷纷裁员,人们逐渐流向城市。"}},{"pos":"VERB 动词","cn":"(声音等)传到,传出","en":"If sounds drift somewhere, they can be heard but they are not very loud.","ex":{"en":"Cool summer dance sounds are drifting from the stereo indoors.","cn":"清凉的夏日舞曲的声音从室内音响中传了出来。"}},{"pos":"VERB 动词","cn":"(雪)吹积,堆积","en":"If snow drifts, it builds up into piles as a result of the movement of the wind.","ex":{"en":"The snow, except where it drifted, was only calf-deep","cn":"除了吹得堆积起来的地方,雪只有小腿肚深。"}},{"pos":"N-COUNT 可数名词","cn":"雪堆","en":"A drift is a mass of snow that has built up into a pile as a result of the movement of wind.","ex":{"en":"...a nine-foot snow drift.","cn":"9英尺深的雪堆"}},{"pos":"N-COUNT 可数名词","cn":"吹积物;飘浮物;漂流物","en":"A drift of something is an amount of it that has been created by the movement of wind or water.","ex":{"en":"There was a drift of smoke above the trees.","cn":"树林上空飘浮着一股烟。"}},{"pos":"N-SING 单数名词","cn":"(论点或演说的)主旨,大意","en":"The drift of an argument or speech is the general point that is being made in it.","ex":{"en":"Grace was beginning to get his drift","cn":"格雷丝慢慢明白了他的意思。"}},{"pos":"","cn":"","en":"相关词组：drift off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start to live apart from a sexual partner you used to live with or are married to","cn":""},{"en":"if two people split up , they stop having a relationship with each other, especially a sexual relationship","cn":""},{"en":"to separate from someone so that your relationship ends - used especially in literature","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v 4 v ","senses":[{"en":"If you get my drift , you get the basic meaning of what I'm saying. Or, if you move around without a seeming fixed destination, you are said to drift — whether you're a snowflake or a homeless person."}]},"collocations":{"phrases":["ADJ. gradual, slow","PREP. ~ (away) from the drift of people away from rural areas into urban slums | ~ (back) to As the strike went on, there was a gradual drif","ADJ. general, main","VERB + DRIFT catch, follow, get I didn't follow the speech exactly, but I caught the main drift of what was being said. | lose I lost the dr","ADJ. deep, great | sand, snow (also snowdrift)"]},"media":{"uk":"media/ldoce/hwd/bre/0/drift_v0205.mp3","us":"media/ldoce/hwd/ame/3/drift1.mp3"},"examples":[{"en":"As children we were very close, but as we grew up we just drifted apart.","cn":"孩提时我们亲密无间，但长大后我们就逐渐疏远了。"},{"en":"The injured man tried to speak but soon drifted into unconsciousness.","cn":"受伤的男人想说点什么，但一会儿就不省人事了。"}],"oxford":{"phon":"drɪft","pos":"verb","senses":[{"en":"to move along smoothly and slowly in water or air","cn":"漂流；漂移；飘","g":"[intransitive]","sc":"move slowly","ex":{"en":"Clouds drifted across the sky.","cn":"朵朵浮云在空中飘过。"}},{"en":"to move or go somewhere slowly","cn":"缓缓移动；缓慢行走","g":"[intransitive]","sc":"move slowly","ex":{"en":"The crowd drifted away from the scene of the accident.","cn":"人群渐渐从事故现场散去。"}},{"en":"to do something, happen or change without a particular plan or purpose","cn":"无意间发生；无目的地转变；顺其自然地做","g":"[intransitive]","sc":"without purpose","ex":{"en":"I didn't intend to be a teacher—I just drifted into it.","cn":"我并没打算过当老师，只是顺其自然就当了。"}},{"en":"to go from one situation or state to another without realizing it","cn":"无意间进入；不知不觉陷入","g":"[intransitive]","sc":"into state/situation","ex":{"en":"Finally she drifted into sleep.","cn":"最后她不知不觉地睡着了。"}},{"en":"to be blown into large piles by the wind","cn":"吹积；堆积","g":"[intransitive]","sc":"of snow/sand","ex":{"en":"drifting sand","cn":"堆积的沙"}},{"en":"to make something float somewhere","cn":"使漂流；使漂浮","g":"[transitive]","sc":"float","ex":{"en":"The logs are drifted downstream to the mill.","cn":"原木顺流而下漂到木材加工厂。"}},{"en":"a slow steady movement from one place to another; a slow change or development from one situation to another, especially to something bad","cn":"流动；趋势；缓慢变化（尤指向坏的方面）","g":"[singular, uncountable]","sc":"slow movement","ex":{"en":"the drift of people away from rural areas into urban slums","cn":"由农村到城市贫民区的人口流动"},"pos":"noun"},{"en":"the movement of a ship or plane away from its direction because of currents or wind","cn":"（船只或飞机的）偏航，航差","g":"[uncountable]","sc":"of ship","ex":{"en":"Remember to allow for drift.","cn":"记住要允许漂移。"},"pos":"noun"},{"en":"the movement of the sea or air","cn":"水流；气流；流动","g":"[uncountable, countable]","sc":"of sea/air","ex":{"en":"the general direction of drift on the east coast","cn":"东海岸海水的总体流向"},"pos":"noun"},{"en":"a large pile of something, especially snow, made by the wind","cn":"吹聚物；雪堆","g":"[countable]","sc":"of snow","ex":{"en":"The road was blocked by deep drifts of snow.","cn":"道路被风吹来的厚厚积雪阻塞。"},"pos":"noun"},{"en":"a large mass of something, especially flowers","cn":"大丛的花；丛生的植物","g":"[countable]","sc":"of flowers","ex":{"en":"Plant daffodils in informal drifts.","cn":"随便种几丛黄水仙。"},"pos":"noun"},{"en":"the general meaning of what somebody says or writes","cn":"大意；主旨；要点","g":"[singular]","sc":"meaning","ex":{"en":"Do you catch my drift?","cn":"你大概明白我的意思吗？"},"pos":"noun"}]}}});
